INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C1','math',2,2,'u5',2,'자료를 분류하여 표로 나타내기 — 기준을 정해 같은 것끼리 모으고, ／ 표시를 하며 빠짐없이 세어 수로 적기',ARRAY['2수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C2','math',2,2,'u5',2,'표의 합계와 편리한 점 — 항목별 수를 모두 더한 합계가 전체 수임을 알고, 자료와 표가 각각 무엇을 알기 좋은지 말하기',ARRAY['2수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C3','math',2,2,'u5',3,'자료를 조사하는 방법 — 말하기·손 들기·이름 붙이기 등 알맞은 방법을 고르고, 빠진 사람 없이 조사하기',ARRAY['2수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C4','math',2,2,'u5',3,'조사한 자료를 표로 나타내기 — 제목·항목·수·합계를 갖추어 표를 만들고, ／ 표시를 세어 빈칸을 채우며 합계로 확인하기',ARRAY['2수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C5','math',2,2,'u5',4,'그래프를 그리는 차례 — 가로·세로에 나타낼 것을 정하고 가장 큰 수만큼 칸을 나누며, 가로와 세로를 바꾸어도 수는 같음을 알기',ARRAY['2수04-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C6','math',2,2,'u5',4,'맨 아래부터 빠짐없이 그리기 — ◯·×·／를 한 칸에 하나씩 맨 아래부터 빠짐없이 그리고, 표와 그래프의 수가 같게 옮기며 잘못 그린 곳 찾기',ARRAY['2수04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C7','math',2,2,'u5',5,'표와 그래프 읽기 — 표에서 수와 합계를, 그래프에서 많고 적음을 읽고 차이·「n보다 많은」을 찾으며 둘의 편리한 점을 가리기',ARRAY['2수04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C8','math',2,2,'u5',6,'조사하여 표와 그래프로 나타내기 — 우리 반을 조사해 표와 그래프로 옮기고, 알게 된 것을 그대로 적어 전하기',ARRAY['2수04-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X01','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'세다가 빠뜨리거나 두 번 세어 수가 하나 어긋난다','센 것에 ／ 표시를 하며 하나씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X02','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C7']::text[],'자료에서 묻는 항목이 아닌 것까지 세거나 이웃 칸의 수를 읽는다','묻는 항목 이름에 동그라미를 치고 그것만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X03','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C7','M2-2-u5-C8']::text[],'합계와 한 칸의 수를 섞는다 — 가장 큰 수를 합계로, 합계를 한 항목의 수로 답한다','합계는 모든 칸을 더한 수 — 한 칸보다 언제나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X04','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 가지」와 「몇 명」을 섞는다 — 항목 수를 학생 수로, 학생 수를 가짓수로 답한다','가지는 칸의 수, 명은 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X05','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4']::text[],'표의 빈칸을 합계에서 빼지 않고 나머지 칸의 합을 그대로 쓴다','합계 − 나머지 칸의 합 = 빈칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X06','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C8']::text[],'／ 표시를 셀 때 다섯 묶음을 4나 6으로 세거나 한 줄을 통째로 빠뜨린다','／／／／／ 한 묶음은 5 — 5, 10 하고 묶음부터 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X07','math',2,'u5',ARRAY['M2-2-u5-C7','M2-2-u5-C8']::text[],'많고 적음을 수가 아니라 칸의 자리나 이름으로 판단한다(맨 앞 칸이 가장 많다)','수를 보고 견주기 — 그래프는 높이, 표는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X08','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 더 많은」을 묻는데 두 수를 더하거나, 「모두 몇」을 묻는데 뺀다','더 많은 → 빼기, 모두 → 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X09','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C5','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 아닌↔맞는, 바른↔잘못된','물음의 「가장·아닌·잘못」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X10','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'◯를 위에서부터 그리거나 중간 칸을 건너뛰어 그린다','맨 아래 칸부터 한 칸에 하나씩 빠짐없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X11','math',2,'u5',ARRAY['M2-2-u5-C6','M2-2-u5-C8']::text[],'표의 수와 그래프의 ◯ 수를 다르게 옮긴다(하나 많거나 적게)','표의 수를 짚어 가며 ◯를 하나씩 세어 그리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X12','math',2,'u5',ARRAY['M2-2-u5-C5']::text[],'그래프의 칸 수를 합계나 항목 수로 잡는다(칸이 모자라거나 빈 칸이 많이 남음)','세로 칸 수 = 가장 큰 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X13','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'한 그래프에 기호를 섞어 쓰거나, 가로와 세로를 바꾸면 수도 달라진다고 여긴다','기호는 한 가지로 — 자리를 바꿔도 수는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X14','math',2,'u5',ARRAY['M2-2-u5-C7']::text[],'「n보다 많은」에 딱 n인 것을 넣는다(경곗값)','n인 칸 위에 선을 긋고 그 위에 ◯가 있는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X15','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C8']::text[],'조사·표 만들기의 절차를 어긴다 — 기준 없이 모으기, 몇 명만 조사하기, 제목·합계 빠뜨리기, 합계를 마음대로 고치기','모두 조사 → 기준에 따라 모으기 → 제목·항목·수·합계') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X16','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7','M2-2-u5-C8']::text[],'자료·표·그래프가 각각 알기 좋은 것을 뒤바꾼다(표에서 누가 골랐는지 안다, 그래프가 수를 알기 좋다)','자료는 누가, 표는 수와 합계, 그래프는 많고 적음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#1','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'sa','auto','놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「놀이 한마당」 칸 아래의 수를 읽어요.","놀이 한마당이 즐거웠던 학생은 5명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["5","5명"],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#2','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 현장체험학습이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 현장체험학습이 즐거웠던 학생은 몇 명인가요?","explanation":["자료에서 「현장체험학습」을 고른 이름표만 ／ 표시를 하며 세어요.","현장체험학습이 즐거웠던 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"act","items":[["호진","현장체험학습"],["재이","현장체험학습"],["효주","놀이 한마당"],["연우","안전 체험"],["상혁","안전 체험"],["수찬","신나는 무용"],["시후","놀이 한마당"],["세미","신나는 무용"],["슬기","놀이 한마당"],["민하","현장체험학습"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#3','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','자료를 분류하여 표로 나타낼 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X16']::text[],true,'{"seq":3,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 분류하여 표로 나타낼 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"기준을 정해 같은 것끼리 모은다","correct":true},{"t":"합계부터 쓴다","mis":"M2-2-u5-X15"},{"t":"그래프를 그린다","mis":"M2-2-u5-X16"}],"explanation":["먼저 무엇을 기준으로 나눌지 정해요.","같은 것끼리 모은 다음 세어서 수로 적어요.","합계는 수를 다 적은 뒤에 더해서 써요."],"variant_rule":{"alt":[{"stem":"분류한 칸의 이름을 세어서 수로 적은 것을 무엇이라고 하나요?","options":[{"t":"표","correct":true},{"t":"그래프","mis":"M2-2-u5-X16"},{"t":"자료","mis":"M2-2-u5-X16"}],"explanation":["분류한 칸마다 몇 개인지 세어 수로 적어요.","그렇게 적은 것이 표예요.","그래프는 ◯를 쌓아 나타낸 것이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#4','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',1,'mc','auto','슬기네 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"슬기네 반 학생은 모두 몇 명인가요?","explanation":["표의 각 활동별 수는 현장체험학습 7명, 안전 체험 3명, 놀이 한마당 5명, 신나는 무용 2명, 텃밭 가꾸기 3명이에요.","7 + 3 + 5 + 2 + 3 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"7명","mis":"M2-2-u5-X03"},{"t":"5명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#5','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'mc','auto','신나는 무용이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":5,"concept":"M2-2-u5-C1","difficulty":2,"kind":"mc","stem":"신나는 무용이 즐거웠던 학생은 몇 명인가요?","explanation":["표에서 「신나는 무용」 칸 아래의 수를 읽어요.","신나는 무용이 즐거웠던 학생은 2명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"options":[{"t":"2명","correct":true},{"t":"3명","mis":"M2-2-u5-X01"},{"t":"1명","mis":"M2-2-u5-X01"},{"t":"7명","mis":"M2-2-u5-X02"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#6','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'ox','auto','표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.',ARRAY['M2-2-u5-X16']::text[],true,'{"seq":6,"concept":"M2-2-u5-C2","difficulty":2,"kind":"ox","stem":"표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.","answer":"X","reason_options":[{"t":"표에는 활동별 학생 수만 있고 누가 골랐는지는 없으니까","correct":true},{"t":"표에는 조사한 것이 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"mis":"M2-2-u5-X16","explanation":["표에는 활동별 학생 수와 합계만 적혀 있어요.","누가 무엇을 골랐는지는 자료(이름표)를 봐야 알아요.","표는 활동별 학생 수를 한눈에 알기 좋아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"표를 보면 활동별로 몇 명인지 한눈에 알 수 있어요.","answer":"O","reason_options":[{"t":"활동마다 수가 적혀 있으니까","correct":true},{"t":"이름이 하나씩 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"explanation":["표에는 활동별 학생 수가 수로 적혀 있어요.","그래서 몇 명인지 바로 읽을 수 있어요.","이름은 자료에만 있어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#7','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'match','auto','분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C1","difficulty":2,"kind":"match","stem":"분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"안전 체험 — 채원·세미·도현","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"},{"l":"놀이 한마당 — 지은·시후·다윤·정우·소민","r":"5명"}],"mis":"M2-2-u5-X01","explanation":["칸에 모인 이름을 하나씩 세요.","안전 체험 3명, 신나는 무용 2명이에요.","놀이 한마당은 5명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"현장체험학습 — 서준·소희·재이·효주·슬기·우영·수찬","r":"7명"},{"l":"텃밭 가꾸기 — 상혁·연우·민하","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"}],"explanation":["칸에 모인 이름을 하나씩 세요.","현장체험학습 7명, 텃밭 가꾸기 3명이에요.","신나는 무용은 2명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#8','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 3 + 5 + 2 + 3 = 13이에요.","13 + □ = 20이니 □ = 7이에요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["7"],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[null,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#9','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'mc','auto','현장체험학습이 즐거웠던 학생과 놀이 한마당이 즐거웠던 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"현장체험학습이 즐거웠던 학생과 놀이 한마당이 즐거웠던 학생은 모두 몇 명인가요?","explanation":["현장체험학습이 즐거웠던 학생은 7명, 놀이 한마당이 즐거웠던 학생은 5명이에요.","7 + 5 = 12이니 모두 12명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"12명","correct":true},{"t":"2명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#10','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',3,'error','auto','표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X16']::text[],true,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수찬 — 「합계가 20이니까 현장체험학습을 고른 학생이 20명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"지아 — 「활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"연우 — 「7 + 3 + 5 + 2 + 3 = 20이니까 합계는 20이야.」","mis":"M2-2-u5-X16"}],"explanation":["합계 20은 모든 활동의 학생 수를 더한 수예요.","현장체험학습은 7명이에요.","수찬이는 합계를 한 활동의 수로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「가장 큰 수가 7이니까 슬기네 반은 7명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"서아 — 「놀이 한마당이 즐거웠던 학생은 5명이야.」","mis":"M2-2-u5-X16"},{"t":"민수 — 「합계 20이 슬기네 반 학생 수야.」","mis":"M2-2-u5-X16"}],"explanation":["반 학생 수는 합계 20명이에요.","7은 현장체험학습 한 칸의 수예요.","하람이는 한 칸의 수를 전체로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#1','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',2,'sa','auto','파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":2,"kind":"sa","stem":"파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.","explanation":["표에서 「파란색」 칸 아래의 수를 읽어요.","파란색 연결 모형은 10개예요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["10","10개"],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#2','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',2,'mc','auto','슬기네 모둠의 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":2,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"슬기네 모둠의 연결 모형은 모두 몇 개인가요?","explanation":["표의 각 색깔별 수는 주황색 9개, 파란색 10개, 노란색 8개예요.","9 + 10 + 8 = 27이니 모두 27개예요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"27개","correct":true},{"t":"10개","mis":"M2-2-u5-X03"},{"t":"3개","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#3','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',3,'mc','auto','자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":3,"concept":"M2-2-u5-C1","difficulty":3,"kind":"mc","stem":"자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?","explanation":["자료에서 「놀이 한마당」을 고른 이름표만 ／ 표시를 하며 세어요.","놀이 한마당이 즐거웠던 학생은 2명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"2명","correct":true},{"t":"3명","mis":"M2-2-u5-X01"},{"t":"1명","mis":"M2-2-u5-X01"},{"t":"4명","mis":"M2-2-u5-X02"}],"asset":{"type":"cards","topic":"act","items":[["세미","현장체험학습"],["소민","안전 체험"],["소희","안전 체험"],["채원","현장체험학습"],["연우","놀이 한마당"],["상혁","현장체험학습"],["수찬","안전 체험"],["정우","신나는 무용"],["효주","놀이 한마당"],["도현","현장체험학습"],["다윤","신나는 무용"],["재이","신나는 무용"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#4','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?","options":[{"t":"13명","correct":true},{"t":"7명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"12명","mis":"M2-2-u5-X01"}],"explanation":["현장체험학습이 아닌 활동은 안전 체험·놀이 한마당·신나는 무용·텃밭 가꾸기예요.","3 + 5 + 2 + 3 = 13이에요.","합계 20에서 7을 빼도 13이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#5','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','현장체험학습이 즐거웠던 학생은 놀이 한마당이 즐거웠던 학생보다 몇 명 더 많은가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 즐거웠던 학생은 놀이 한마당이 즐거웠던 학생보다 몇 명 더 많은가요?","explanation":["현장체험학습이 즐거웠던 학생은 7명, 놀이 한마당이 즐거웠던 학생은 5명이에요.","7 − 5 = 2이니 2명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"options":[{"t":"2명","correct":true},{"t":"12명","mis":"M2-2-u5-X08"},{"t":"7명","mis":"M2-2-u5-X08"},{"t":"3명","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#6','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',3,'ox','auto','「현장체험학습」을 센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":6,"concept":"M2-2-u5-C1","difficulty":3,"kind":"ox","stem":"「현장체험학습」을 센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.","answer":"O","reason_options":[{"t":"센 것과 아직 안 센 것이 구분되니까","correct":true},{"t":"표시를 하면 수가 늘어나니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["센 낱장에 표시를 하면 어디까지 셌는지 보여요.","그래서 빠뜨리거나 두 번 세지 않아요.","표시는 수를 바꾸지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#7','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'error','auto','자료와 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":7,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"자료와 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「표를 보면 효주가 무엇을 골랐는지 바로 알 수 있어.」","correct":true,"mis_target":"M2-2-u5-X16"},{"t":"소율 — 「자료를 보면 누가 무엇을 골랐는지 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"예준 — 「표를 보면 활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"}],"explanation":["자료(이름표)에는 누가 무엇을 골랐는지 적혀 있어요.","표에는 활동별 학생 수와 합계가 있어요.","효주가 고른 활동은 표가 아니라 자료에서 찾아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#8','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'essay','teacher','표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":4,"kind":"essay","stem":"표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 활동별 학생 수 7, 3, 5, 2, 3을 모두 더해서 7 + 3 + 5 + 2 + 3 = 20으로 구했다. 합계는 조사한 학생 전체의 수, 곧 슬기네 반 학생 수이다.","scoring_points":["항목별 수를 모두 더했음을 썼는가","7 + 3 + 5 + 2 + 3 = 20을 썼는가","합계가 전체 학생 수임을 썼는가"]},"explanation":["합계는 항목별 수를 모두 더한 수예요.","7 + 3 + 5 + 2 + 3 = 20이에요.","합계 20명이 슬기네 반 전체 학생 수예요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#9','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',4,'essay','teacher','자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C1","difficulty":4,"kind":"essay","stem":"자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.","answer_guide":{"answer":"예: 표로 나타내면 활동별 학생 수를 한눈에 알 수 있고 합계도 바로 알 수 있다. 자료에서는 누가 어떤 활동을 골랐는지 알 수 있다.","scoring_points":["표의 좋은 점(활동별 수·합계를 한눈에)을 썼는가","자료에서만 알 수 있는 것(누가 무엇을 골랐는지)을 썼는가","둘을 구분해서 썼는가"]},"explanation":["표는 활동별 학생 수와 합계를 한눈에 보여 줘요.","자료는 누가 무엇을 골랐는지 보여 줘요.","표와 자료는 알기 좋은 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#10','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'mc','auto','표에서 두 번째로 많은 학생이 즐거워한 활동은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],false,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":4,"kind":"mc","stem":"표에서 두 번째로 많은 학생이 즐거워한 활동은 무엇인가요?","options":[{"t":"놀이 한마당","correct":true},{"t":"현장체험학습","mis":"M2-2-u5-X09"},{"t":"안전 체험","mis":"M2-2-u5-X07"},{"t":"신나는 무용","mis":"M2-2-u5-X09"}],"explanation":["수가 큰 순서로 늘어놓으면 7, 5, 3, 3, 2예요.","가장 많은 것은 현장체험학습(7명)이에요.","두 번째로 많은 것은 놀이 한마당(5명)이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#1','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'mc','auto','자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"빠진 친구가 없도록 모두 조사한다","correct":true},{"t":"빨리 끝나도록 몇 명만 조사한다","mis":"M2-2-u5-X15"},{"t":"한 친구에게 두 번씩 물어본다","mis":"M2-2-u5-X01"}],"explanation":["조사는 빠진 사람이 없어야 해요.","몇 명만 조사하면 우리 반의 결과가 아니에요.","한 사람에게 두 번 물으면 두 번 세게 돼요."],"variant_rule":{"alt":[{"stem":"조사하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 친구에게만 물어본다","correct":true},{"t":"한 사람씩 차례로 말한다","mis":"M2-2-u5-X15"},{"t":"계절별로 손을 들어 센다","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","한 사람씩 말하거나 손을 들게 하면 모두 조사할 수 있어요.","몇 명만 고르면 빠진 친구가 생겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#2','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'match','auto','태어난 달을 보고 알맞은 계절과 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C3","difficulty":1,"kind":"match","stem":"태어난 달을 보고 알맞은 계절과 이으세요.","pairs":[{"l":"4월","r":"봄"},{"l":"7월","r":"여름"},{"l":"1월","r":"겨울"}],"mis":"M2-2-u5-X02","explanation":["3·4·5월은 봄, 6·7·8월은 여름이에요.","9·10·11월은 가을이에요.","12·1·2월은 겨울이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 태어난 달을 보고 알맞은 계절과 이으세요.","pairs":[{"l":"10월","r":"가을"},{"l":"6월","r":"여름"},{"l":"2월","r":"겨울"}],"explanation":["6·7·8월은 여름이에요.","9·10·11월은 가을이에요.","12·1·2월은 겨울이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#3','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'sa','auto','가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C4","difficulty":1,"kind":"sa","stem":"가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「가을」 칸 아래의 수를 읽어요.","가을에 태어난 학생은 6명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["6","6명"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#4','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":4,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「봄」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"7","correct":true},{"t":"6","mis":"M2-2-u5-X06"},{"t":"8","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[null,4,6,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#5','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 7 + 6 + 3 = 16이에요.","16 + □ = 20이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["4"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,null,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#6','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','표에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?',ARRAY['M2-2-u5-X15']::text[],true,'{"seq":6,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"표에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?","options":[{"t":"조사한 친구들의 이름","correct":true},{"t":"무엇을 조사했는지 알려 주는 제목","mis":"M2-2-u5-X15"},{"t":"모두 더한 합계","mis":"M2-2-u5-X15"}],"explanation":["표에는 제목·항목·수·합계를 갖추어요.","이름은 자료에 있고 표에는 수만 적어요.","제목이 없으면 무엇을 조사했는지 알 수 없어요."],"variant_rule":{"alt":[{"stem":"표의 제목은 무엇을 알려 주나요?","options":[{"t":"무엇을 조사했는지","correct":true},{"t":"합계가 얼마인지","mis":"M2-2-u5-X03"},{"t":"누가 조사했는지","mis":"M2-2-u5-X16"}],"explanation":["제목은 무엇을 조사한 표인지 알려 줘요.","「우리 반 친구들이 태어난 계절별 학생 수」처럼 써요.","합계는 표 맨 끝 칸에 따로 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#7','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',2,'ox','auto','조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":7,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.","answer":"O","reason_options":[{"t":"말하기·손 들기·이름 붙이기 가운데 조사할 것에 맞는 방법을 고르니까","correct":true},{"t":"조사 방법은 언제나 한 가지뿐이니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["조사 방법에는 말하기, 손 들기, 이름 써서 붙이기 등이 있어요.","무엇을 조사하느냐에 따라 알맞은 방법이 달라요.","어떤 방법이든 빠진 친구가 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#8','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','봄에 태어난 학생과 여름에 태어난 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":8,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"봄에 태어난 학생과 여름에 태어난 학생은 모두 몇 명인가요?","explanation":["봄에 태어난 학생은 7명, 여름에 태어난 학생은 4명이에요.","7 + 4 = 11이니 모두 11명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"11명","correct":true},{"t":"3명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#9','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','우리 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X01']::text[],true,'{"seq":9,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"우리 반 학생은 모두 몇 명인가요?","explanation":["표의 각 과일별 수는 자두 3명, 포도 5명, 키위 2명, 감 4명, 복숭아 4명이에요.","3 + 5 + 2 + 4 + 4 = 18이니 모두 18명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"18명","correct":true},{"t":"5명","mis":"M2-2-u5-X03"},{"t":"19명","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감","복숭아"],"counts":[3,5,2,4,4],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#10','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',3,'error','auto','친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X15']::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"윤슬 — 조사한 친구가 적어서 합계를 25로 늘려 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"가은 — 제목을 「우리 반 친구들이 태어난 계절별 학생 수」라고 썼다","mis":"M2-2-u5-X15"},{"t":"태오 — 7 + 4 + 6 + 3을 더해 합계 20을 썼다","mis":"M2-2-u5-X15"}],"explanation":["합계는 항목별 수를 더한 그대로 적어요.","마음대로 늘려 쓰면 조사한 것이 아니에요.","제목을 쓰고 더해서 합계를 쓴 것은 바르게 만든 거예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"도윤 — 제목 없이 수만 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 계절 칸을 봄·여름·가을·겨울로 나누어 적었다","mis":"M2-2-u5-X15"},{"t":"서아 — 합계 칸에 20을 적었다","mis":"M2-2-u5-X15"}],"explanation":["표에는 무엇을 조사한 것인지 제목을 써야 해요.","항목을 나누고 합계를 쓴 것은 바르게 만든 거예요.","제목·항목·수·합계를 다 갖추어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#1','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',2,'mc','auto','겨울에 태어난 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":1,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"겨울에 태어난 학생은 몇 명인가요?","explanation":["표에서 「겨울」 칸 아래의 수를 읽어요.","겨울에 태어난 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"},{"t":"7명","mis":"M2-2-u5-X02"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#2','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["「팥」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"variant_rule":{"tg":{"ask":"tally"}},"answer":["7"],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[null,5,2,3,4],"unit":"명","vh":"학생 수","tally":[7,5,2,3,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#3','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X05','M2-2-u5-X01']::text[],true,'{"seq":3,"concept":"M2-2-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["나머지 칸을 더하면 3 + 5 + 2 + 4 = 14예요.","14 + □ = 18이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"options":[{"t":"4","correct":true},{"t":"18","mis":"M2-2-u5-X03"},{"t":"14","mis":"M2-2-u5-X05"},{"t":"5","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감","복숭아"],"counts":[3,5,2,4,null],"unit":"명","vh":"학생 수","total":18}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#4','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',3,'mc','auto','한 사람씩 차례로 말하기로 조사하면 좋은 점은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":3,"kind":"mc","stem":"한 사람씩 차례로 말하기로 조사하면 좋은 점은 무엇인가요?","options":[{"t":"차례가 분명해서 빠뜨리기 어렵다","correct":true},{"t":"손을 들지 않아도 되니 빨리 끝난다","mis":"M2-2-u5-X15"},{"t":"말한 친구만 표에 넣어도 된다","mis":"M2-2-u5-X15"},{"t":"이름을 적지 않아도 된다","mis":"M2-2-u5-X01"}],"explanation":["한 사람씩 말하면 누가 말했고 안 했는지 분명해요.","그래서 빠뜨리기 어려워요.","말한 친구의 이름을 계절 칸에 적어 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#5','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'sa','auto','봄에 태어난 학생은 겨울에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":3,"kind":"sa","stem":"봄에 태어난 학생은 겨울에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["봄에 태어난 학생은 7명, 겨울에 태어난 학생은 3명이에요.","7 − 3 = 4이니 4명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["4","4명"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#6','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',3,'ox','auto','우리 반은 20명인데 표의 합계가 19이면 어딘가를 빠뜨리거나 두 번 센 거예요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":6,"concept":"M2-2-u5-C4","difficulty":3,"kind":"ox","stem":"우리 반은 20명인데 표의 합계가 19이면 어딘가를 빠뜨리거나 두 번 센 거예요.","answer":"O","reason_options":[{"t":"합계는 조사한 전체 수라 반 학생 수와 같아야 하니까","correct":true},{"t":"합계는 반 학생 수와 상관없으니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["합계는 조사한 모든 친구의 수예요.","반 전체를 조사했으면 합계는 반 학생 수와 같아야 해요.","다르면 빠뜨리거나 두 번 센 거니 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#7','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',3,'error','auto','조사 방법을 정하는 친구들의 말 가운데 잘못된 것은 무엇인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":7,"concept":"M2-2-u5-C3","difficulty":3,"kind":"error","stem":"조사 방법을 정하는 친구들의 말 가운데 잘못된 것은 무엇인가요?","options":[{"t":"도윤 — 「내가 좋아하는 친구들에게만 물어보면 돼.」","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 「계절별로 손을 들게 하고 세어도 돼.」","mis":"M2-2-u5-X15"},{"t":"서아 — 「이름을 써서 계절 칸에 붙여도 돼.」","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","손 들기, 이름 붙이기는 모두 알맞은 방법이에요.","몇 명에게만 물으면 빠진 친구가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#8','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',4,'essay','teacher','우리 반 친구들이 태어난 계절을 조사해 표로 만들 때 꼭 갖추어야 할 것을 쓰고, 합계가 필요한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C4","difficulty":4,"kind":"essay","stem":"우리 반 친구들이 태어난 계절을 조사해 표로 만들 때 꼭 갖추어야 할 것을 쓰고, 합계가 필요한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 표에는 제목, 항목(봄·여름·가을·겨울), 항목별 학생 수, 합계를 갖추어야 한다. 합계는 조사한 전체 수이므로 반 학생 수와 같은지 보고 빠뜨린 친구가 없는지 확인할 수 있다.","scoring_points":["제목·항목·수·합계를 썼는가","합계가 전체 수임을 썼는가","합계로 빠짐을 확인할 수 있음을 썼는가"]},"explanation":["표에는 제목·항목·수·합계를 갖추어요.","합계는 조사한 전체 수예요.","합계가 반 학생 수와 같으면 빠뜨린 친구가 없는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#9','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C3',4,'essay','teacher','친구들이 좋아하는 과일을 조사하려고 해요. 어떤 방법으로 조사할지 정하고, 빠뜨리지 않고 조사하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"친구들이 좋아하는 과일을 조사하려고 해요. 어떤 방법으로 조사할지 정하고, 빠뜨리지 않고 조사하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 한 사람씩 차례로 좋아하는 과일을 말하게 하고, 말한 친구의 이름을 과일 칸에 적어 둔다. 다 끝나면 이름 수를 세어 반 학생 수와 같은지 확인한다.","scoring_points":["조사 방법을 하나 정했는가","말한(조사한) 친구를 표시하는 방법을 썼는가","전체 수와 견주어 확인하는 것을 썼는가"]},"explanation":["조사 방법은 말하기, 손 들기, 이름 붙이기 등에서 골라요.","조사한 친구를 적어 두면 빠뜨리지 않아요.","다 세고 반 학생 수와 같은지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#10','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',4,'mc','auto','표를 보고 바르게 말한 것은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X08','M2-2-u5-X04']::text[],false,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":4,"kind":"mc","stem":"표를 보고 바르게 말한 것은 무엇인가요?","options":[{"t":"가을에 태어난 학생은 겨울에 태어난 학생의 2배예요","correct":true},{"t":"봄에 태어난 학생이 여름에 태어난 학생보다 적어요","mis":"M2-2-u5-X09"},{"t":"여름과 겨울에 태어난 학생은 모두 6명이에요","mis":"M2-2-u5-X08"},{"t":"우리 반 학생은 모두 4명이에요","mis":"M2-2-u5-X04"}],"explanation":["가을 6명, 겨울 3명 — 6은 3의 2배예요.","봄 7명은 여름 4명보다 많고, 여름 4 + 겨울 3 = 7명이에요.","4는 계절 가짓수이고 반 학생 수는 합계 20명이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#1','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',1,'sa','auto','고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C6","difficulty":1,"kind":"sa","stem":"고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「고양이」 칸에 ◯가 몇 개 쌓였는지 세어요.","고양이를 좋아하는 학생은 5명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["5","5명"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#2','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',1,'error','auto','그래프를 그리는 차례를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X15']::text[],true,'{"seq":2,"concept":"M2-2-u5-C5","difficulty":1,"kind":"error","stem":"그래프를 그리는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지후 — 「◯는 위에서부터 아래로 그려야 해.」","correct":true,"mis_target":"M2-2-u5-X10"},{"t":"민솔 — 「먼저 가로와 세로에 무엇을 나타낼지 정해.」","mis":"M2-2-u5-X15"},{"t":"다온 — 「가장 큰 수만큼 칸을 나눠.」","mis":"M2-2-u5-X15"}],"explanation":["그래프는 가로·세로 정하기 → 칸 나누기 → ◯ 채우기 → 제목 쓰기 차례예요.","◯는 맨 아래 칸부터 빠짐없이 채워요.","위에서부터 그리면 안 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그래프를 그리는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「◯ 사이를 한 칸씩 띄워서 그려야 해.」","correct":true,"mis_target":"M2-2-u5-X10"},{"t":"가은 — 「가로에 동물, 세로에 학생 수를 써.」","mis":"M2-2-u5-X15"},{"t":"태오 — 「다 그린 뒤에 제목을 써.」","mis":"M2-2-u5-X15"}],"explanation":["◯는 중간을 건너뛰지 않고 빠짐없이 채워요.","가로·세로를 정하고 다 그린 뒤 제목을 써요.","한 칸에 하나씩 맨 아래부터 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#3','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":3,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 개 6명이에요.","◯를 6개까지 쌓아야 하니 세로는 6칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"6칸","correct":true},{"t":"20칸","mis":"M2-2-u5-X12"},{"t":"5칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#4','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',1,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":4,"concept":"M2-2-u5-C6","difficulty":1,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「앵무새」 칸을 보세요.","◯가 위에서부터 채워져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","correct":true},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이"],"counts":[6,3,5],"unit":"명","vh":"학생 수","bad":{"col":1,"how":"top"},"rows":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#5','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'mc','auto','가장 적은 학생이 좋아하는 동물은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":5,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"가장 적은 학생이 좋아하는 동물은 무엇인가요?","explanation":["그래프에서 ◯가 가장 낮게(짧게) 쌓인 칸을 찾아요.","개 6명, 앵무새 3명, 고양이 5명, 토끼 2명, 금붕어 4명이에요 — 가장 적은 것은 토끼(2명)예요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"least","src":"graph"}},"options":[{"t":"토끼","correct":true},{"t":"개","mis":"M2-2-u5-X09"},{"t":"앵무새","mis":"M2-2-u5-X07"},{"t":"고양이","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#6','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',2,'ox','auto','가로와 세로를 바꾸어 그리면 동물별 학생 수도 달라져요.',ARRAY['M2-2-u5-X13']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":2,"kind":"ox","stem":"가로와 세로를 바꾸어 그리면 동물별 학생 수도 달라져요.","answer":"X","reason_options":[{"t":"자리와 기호만 바뀌고 수는 같으니까","correct":true},{"t":"그래프 모양이 달라지면 수도 달라지니까","mis":"M2-2-u5-X13"}],"mis":"M2-2-u5-X13","explanation":["가로와 세로를 바꾸어 그려도 돼요.","동물 종류와 학생 수는 같고, 자리와 기호만 달라요.","개 6명은 세로로 쌓아도 가로로 늘어놓아도 6개예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"같은 자료를 ◯로 세로로 그린 그래프와 ×로 가로로 그린 그래프의 동물별 학생 수는 같아요.","answer":"O","reason_options":[{"t":"같은 표를 보고 그린 것이라 수가 같으니까","correct":true},{"t":"기호가 다르면 수도 다르니까","mis":"M2-2-u5-X13"}],"explanation":["같은 자료를 두 가지 모양으로 나타낸 거예요.","기호와 자리가 달라도 수는 같아요.","개 6명은 어느 그래프에서도 6개예요."],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#7','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'sa','auto','표를 보고 그래프를 완성하려고 해요. 토끼 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":2,"kind":"sa","stem":"표를 보고 그래프를 완성하려고 해요. 토끼 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","explanation":["표에서 토끼는 2명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 2개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"answer":["2","2개"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"blank":[3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#8','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',2,'mc','auto','팥 붕어빵을 좋아하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":8,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"팥 붕어빵을 좋아하는 학생은 몇 명인가요?","explanation":["그래프에서 「팥」 칸에 ／이 몇 개 쌓였는지 세어요.","팥 붕어빵을 좋아하는 학생은 7명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"options":[{"t":"7명","correct":true},{"t":"8명","mis":"M2-2-u5-X01"},{"t":"6명","mis":"M2-2-u5-X01"}],"asset":{"type":"pgraph","mark":"／","dir":"h","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#9','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C5',2,'match','auto','그래프를 그리는 차례에 맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C5","difficulty":2,"kind":"match","stem":"그래프를 그리는 차례에 맞게 이으세요.","pairs":[{"l":"①","r":"가로와 세로에 무엇을 나타낼지 정한다"},{"l":"②","r":"가장 큰 수만큼 칸을 나눈다"},{"l":"③","r":"맨 아래부터 ◯를 채우고 제목을 쓴다"}],"mis":"M2-2-u5-X15","explanation":["먼저 가로와 세로에 무엇을 나타낼지 정해요.","가장 큰 수만큼 칸을 나누어요.","맨 아래부터 ◯를 채우고 제목을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_basic#10','math',2,2,'u5','L04','g2_2_math_u5_L04_basic','lesson_basic','M2-2-u5-C6',3,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":10,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 앵무새는 3명인데 그래프에는 ◯가 4개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"앵무새 — 표는 3명인데 ◯를 4개 그렸다","correct":true},{"t":"개 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"고양이 — 표는 5명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"토끼 — 표는 2명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"drawn":[6,4,5,2,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#1','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',2,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":1,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「보드게임」 칸을 보세요.","◯가 중간 한 칸을 비우고 그 다음 칸에 그려져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"중간 칸을 건너뛰고 그렸다","correct":true},{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","bad":{"col":2,"how":"skip"},"rows":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#2','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',2,'sa','auto','개를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C6","difficulty":2,"kind":"sa","stem":"개를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「개」 칸에 ×가 몇 개 쌓였는지 세어요.","개를 좋아하는 학생은 6명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["6","6명"],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#3','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',3,'sa','auto','표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C5","difficulty":3,"kind":"sa","stem":"표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요? 숫자로 쓰세요.","explanation":["가장 큰 수는 팥 7명이에요.","／을 7개까지 쌓아야 하니 가로는 7칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"answer":["7","7칸"],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#4','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',3,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":4,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 땅따먹기는 4명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"땅따먹기 — 표는 4명인데 ◯를 5개 그렸다","correct":true},{"t":"공기놀이 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"보드게임 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"딱지치기 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"drawn":[5,5,6,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#5','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10']::text[],true,'{"seq":5,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「축구」 칸을 보세요.","◯와 다른 기호가 섞여 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"기호를 섞어서 그렸다","correct":true},{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","mis":"M2-2-u5-X10"},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"sport","title":"우리 반 학생들이 좋아하는 운동별 학생 수","head":"운동","cols":["축구","줄넘기","달리기"],"counts":[5,4,3],"unit":"명","vh":"학생 수","bad":{"col":0,"how":"mix"},"rows":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#6','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',3,'error','auto','앵무새를 좋아하는 학생 3명을 그래프에 나타내는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X10']::text[],false,'{"seq":6,"concept":"M2-2-u5-C6","difficulty":3,"kind":"error","stem":"앵무새를 좋아하는 학생 3명을 그래프에 나타내는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「6칸부터 4칸까지 위에서부터 채워.」","correct":true,"mis_target":"M2-2-u5-X10"},{"t":"윤슬 — 「1칸부터 3칸까지 차례로 채워.」","mis":"M2-2-u5-X10"},{"t":"채윤 — 「◯를 한 칸에 하나씩 3개 그려.」","mis":"M2-2-u5-X10"}],"explanation":["◯는 맨 아래 1칸부터 3칸까지 차례로 채워요.","위에서부터 채우면 안 돼요.","한 칸에 하나씩, 3명이니 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#7','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',3,'ox','auto','가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":7,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.","answer":"X","reason_options":[{"t":"가장 큰 수 6만큼 6칸이면 되고 더 나누면 빈 칸이 남으니까","correct":true},{"t":"칸은 많을수록 좋으니까","mis":"M2-2-u5-X12"}],"mis":"M2-2-u5-X12","explanation":["세로 칸 수는 가장 큰 수만큼이면 돼요.","6명이면 6칸이에요.","10칸으로 나누면 위에 빈 칸이 많이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#8','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',4,'essay','teacher','◯를 맨 아래 칸부터 빠짐없이 채워야 하는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C6","difficulty":4,"kind":"essay","stem":"◯를 맨 아래 칸부터 빠짐없이 채워야 하는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 맨 아래부터 빠짐없이 채워야 ◯의 높이를 보고 몇 명인지 바로 알 수 있고, 어느 것이 많고 적은지 한눈에 견줄 수 있다. 위에서부터 그리거나 중간을 건너뛰면 수를 잘못 읽게 된다.","scoring_points":["높이로 수를 읽을 수 있음을 썼는가","많고 적음을 견줄 수 있음을 썼는가","건너뛰거나 위에서 그리면 안 되는 까닭을 썼는가"]},"explanation":["맨 아래부터 채우면 높이가 곧 수예요.","그래서 많고 적음을 한눈에 견줄 수 있어요.","건너뛰거나 위에서 그리면 수를 잘못 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#9','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C5',4,'essay','teacher','표를 보고 그래프로 나타내는 차례를 설명하고, 가로와 세로를 바꾸어 그려도 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 그래프로 나타내는 차례를 설명하고, 가로와 세로를 바꾸어 그려도 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: ① 가로와 세로에 무엇을 나타낼지 정하고 ② 가장 큰 수 6만큼 세로를 6칸으로 나눈 뒤 ③ 맨 아래부터 ◯를 빠짐없이 채우고 ④ 제목을 쓴다. 가로와 세로를 바꾸어도 동물 종류와 학생 수는 같고 자리와 기호만 달라지므로 바꾸어 그려도 된다.","scoring_points":["차례 네 단계를 썼는가","칸 수를 가장 큰 수로 잡았는가","바꾸어도 수가 같음을 썼는가"]},"explanation":["가로·세로 정하기 → 칸 나누기 → ◯ 채우기 → 제목 쓰기예요.","칸 수는 가장 큰 수 6만큼이에요.","가로와 세로를 바꾸어도 수는 같아요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L04_challenge#10','math',2,2,'u5','L04','g2_2_math_u5_L04_challenge','lesson_challenge','M2-2-u5-C6',4,'mc','auto','표를 보고 그래프를 완성하려고 해요. 로봇 칸에는 ×를 몇 개 그려야 하나요?',ARRAY['M2-2-u5-X11','M2-2-u5-X03']::text[],true,'{"seq":10,"concept":"M2-2-u5-C6","difficulty":4,"kind":"mc","stem":"표를 보고 그래프를 완성하려고 해요. 로봇 칸에는 ×를 몇 개 그려야 하나요?","explanation":["표에서 로봇은 5명이에요.","그래프의 수는 표의 수와 같아야 해요 — ×를 5개 그려요.","맨 왼쪽 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"options":[{"t":"5개","correct":true},{"t":"6개","mis":"M2-2-u5-X11"},{"t":"4개","mis":"M2-2-u5-X11"},{"t":"20개","mis":"M2-2-u5-X03"}],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수","table":true,"blank":[0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#1','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'sa','auto','동호네 반 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C7","difficulty":1,"kind":"sa","stem":"동호네 반 학생은 모두 몇 명인가요? 숫자로 쓰세요.","explanation":["표의 각 전통 놀이별 수는 비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요.","3 + 8 + 2 + 9 = 22이니 모두 22명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"answer":["22","22명"],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#2','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'mc','auto','가장 많은 학생이 좋아하는 전통 놀이는 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":2,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"가장 많은 학생이 좋아하는 전통 놀이는 무엇인가요?","explanation":["그래프에서 ◯가 가장 높이(길게) 쌓인 칸을 찾아요.","비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요 — 가장 많은 것은 공기놀이(9명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most","src":"graph"}},"options":[{"t":"공기놀이","correct":true},{"t":"제기차기","mis":"M2-2-u5-X09"},{"t":"비사치기","mis":"M2-2-u5-X07"},{"t":"투호 놀이","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#3','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'sa','auto','비사치기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C7","difficulty":1,"kind":"sa","stem":"비사치기를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「비사치기」 칸 아래의 수를 읽어요.","비사치기를 좋아하는 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["3","3명"],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#4','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',1,'match','auto','무엇을 알기에 편리한지 알맞게 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u5-C7","difficulty":1,"kind":"match","stem":"무엇을 알기에 편리한지 알맞게 이으세요.","pairs":[{"l":"표","r":"항목별 수와 합계를 바로 읽기"},{"l":"그래프","r":"많고 적음을 한눈에 견주기"},{"l":"자료(이름표)","r":"누가 무엇을 골랐는지 알기"}],"mis":"M2-2-u5-X16","explanation":["표는 항목별 수와 합계를 바로 읽기 좋아요.","그래프는 많고 적음을 한눈에 견주기 좋아요.","누가 무엇을 골랐는지는 자료에서 알아요."],"variant_rule":{"alt":[{"stem":"알고 싶은 것과 편리한 것을 이으세요.","pairs":[{"l":"공기놀이는 몇 명인지 바로 알기","r":"표"},{"l":"어느 놀이가 가장 많은지 한눈에 보기","r":"그래프"}],"explanation":["수를 바로 읽을 때는 표가 편리해요.","많고 적음을 한눈에 볼 때는 그래프가 편리해요.","같은 자료라도 쓰임이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#5','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','3명보다 많은 전통 놀이는 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":5,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"3명보다 많은 전통 놀이는 모두 몇 가지인가요?","explanation":["3명인 칸 위에 선을 긋고 그 위에 ◯가 있는 전통 놀이를 찾아요.","투호 놀이, 공기놀이 — 2가지예요.","「3명보다 많은」에 딱 3명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"2가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"17가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#6','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'sa','auto','공기놀이를 좋아하는 학생은 투호 놀이를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"공기놀이를 좋아하는 학생은 투호 놀이를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["공기놀이를 좋아하는 학생은 9명, 투호 놀이를 좋아하는 학생은 8명이에요.","9 − 8 = 1이니 1명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["1","1명"],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#7','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'ox','auto','「3명보다 많은」 전통 놀이를 찾을 때 딱 3명인 비사치기도 들어가요.',ARRAY['M2-2-u5-X14']::text[],false,'{"seq":7,"concept":"M2-2-u5-C7","difficulty":2,"kind":"ox","stem":"「3명보다 많은」 전통 놀이를 찾을 때 딱 3명인 비사치기도 들어가요.","answer":"X","reason_options":[{"t":"3명은 3명보다 많은 것이 아니니까","correct":true},{"t":"3명도 3명보다 많으니까","mis":"M2-2-u5-X14"}],"mis":"M2-2-u5-X14","explanation":["「3명보다 많은」은 4명, 5명… 처럼 3보다 큰 수예요.","비사치기는 딱 3명이라 들어가지 않아요.","3칸 자리에 선을 긋고 그 위에 ◯가 있는 놀이만 찾아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#8','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','4모둠의 제기차기 횟수는 몇 회인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"4모둠의 제기차기 횟수는 몇 회인가요?","explanation":["그래프에서 「4모둠」 칸에 ◯가 몇 개 쌓였는지 세어요.","4모둠의 제기차기 횟수는 13회예요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"options":[{"t":"13회","correct":true},{"t":"14회","mis":"M2-2-u5-X01"},{"t":"12회","mis":"M2-2-u5-X01"},{"t":"5회","mis":"M2-2-u5-X02"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#9','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',2,'mc','auto','가장 적은 학생이 좋아하는 간식은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":9,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"가장 적은 학생이 좋아하는 간식은 무엇인가요?","explanation":["표에서 수가 가장 작은 칸을 찾아요.","햄버거 5명, 떡볶이 8명, 김밥 4명, 라면 2명이에요 — 가장 적은 것은 라면(2명)이에요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"least"}},"options":[{"t":"라면","correct":true},{"t":"떡볶이","mis":"M2-2-u5-X09"},{"t":"햄버거","mis":"M2-2-u5-X07"}],"asset":{"type":"ftable","topic":"snack","title":"우리 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_basic#10','math',2,2,'u5','L05','g2_2_math_u5_L05_basic','lesson_basic','M2-2-u5-C7',3,'error','auto','표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X07','M2-2-u5-X16']::text[],true,'{"seq":10,"concept":"M2-2-u5-C7","difficulty":3,"kind":"error","stem":"표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채윤 — 「그래프에서 비사치기가 맨 앞에 있으니까 가장 많아.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"하람 — 「공기놀이가 가장 높이 쌓여서 가장 많아.」","mis":"M2-2-u5-X16"},{"t":"윤슬 — 「표를 보면 투호 놀이는 8명이야.」","mis":"M2-2-u5-X16"}],"explanation":["많고 적음은 ◯의 높이로 견주어요.","맨 앞 칸이라고 많은 게 아니에요 — 비사치기는 3명이에요.","가장 높이 쌓인 공기놀이(9명)가 가장 많아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표와 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「제기차기 칸이 가장 뒤에 있으니까 가장 적어.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"가은 — 「◯가 가장 낮게 쌓인 제기차기가 가장 적어.」","mis":"M2-2-u5-X16"},{"t":"태오 — 「동호네 반은 합계 22명이야.」","mis":"M2-2-u5-X16"}],"explanation":["많고 적음은 칸의 자리가 아니라 ◯의 높이로 견주어요.","제기차기(2명)는 ◯가 가장 낮아서 가장 적어요.","자리 때문이 아니라 수 때문이에요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#1','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',2,'mc','auto','투호 놀이를 좋아하는 학생과 공기놀이를 좋아하는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":1,"concept":"M2-2-u5-C7","difficulty":2,"kind":"mc","stem":"투호 놀이를 좋아하는 학생과 공기놀이를 좋아하는 학생은 모두 몇 명인가요?","explanation":["투호 놀이를 좋아하는 학생은 8명, 공기놀이를 좋아하는 학생은 9명이에요.","8 + 9 = 17이니 모두 17명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"17명","correct":true},{"t":"1명","mis":"M2-2-u5-X08"},{"t":"22명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#2','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',2,'sa','auto','4명보다 많은 간식은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"4명보다 많은 간식은 모두 몇 가지인가요? 숫자로 쓰세요.","explanation":["4명인 칸 위에 선을 긋고 그 위에 ◯가 있는 간식을 찾아요.","햄버거, 떡볶이 — 2가지예요.","「4명보다 많은」에 딱 4명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"answer":["2","2가지"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"snack","title":"우리 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#3','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','4모둠의 제기차기 횟수는 1모둠의 제기차기 횟수보다 몇 회 더 많은가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X01']::text[],true,'{"seq":3,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"4모둠의 제기차기 횟수는 1모둠의 제기차기 횟수보다 몇 회 더 많은가요?","explanation":["4모둠의 제기차기 횟수는 13회, 1모둠의 제기차기 횟수는 5회예요.","13 − 5 = 8이니 8회 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"options":[{"t":"8회","correct":true},{"t":"18회","mis":"M2-2-u5-X08"},{"t":"13회","mis":"M2-2-u5-X08"},{"t":"9회","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#4','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','표와 그래프에 대해 바르게 말한 것은 무엇인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":4,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"표와 그래프에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"표는 항목별 수와 합계를, 그래프는 많고 적음을 한눈에 알기 좋다","correct":true},{"t":"표는 많고 적음을, 그래프는 합계를 알기 좋다","mis":"M2-2-u5-X16"},{"t":"표와 그래프는 알 수 있는 것이 똑같다","mis":"M2-2-u5-X16"},{"t":"그래프만 있으면 표는 필요 없다","mis":"M2-2-u5-X16"}],"explanation":["표는 수와 합계를 바로 읽기 좋아요.","그래프는 어느 것이 많고 적은지 한눈에 보여요.","둘은 잘하는 일이 달라서 같이 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#5','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'error','auto','그래프를 보고 친구들이 말했어요. 그래프만으로는 알 수 없는 것을 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":5,"concept":"M2-2-u5-C7","difficulty":3,"kind":"error","stem":"그래프를 보고 친구들이 말했어요. 그래프만으로는 알 수 없는 것을 말한 친구는 누구인가요?","options":[{"t":"지후 — 「소희가 공기놀이를 좋아하는지 알 수 있어.」","correct":true,"mis_target":"M2-2-u5-X16"},{"t":"민솔 — 「가장 많은 학생이 좋아하는 놀이를 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"다온 — 「투호 놀이보다 적은 놀이를 알 수 있어.」","mis":"M2-2-u5-X16"}],"explanation":["그래프에는 놀이별 학생 수와 많고 적음이 나타나요.","누가 어떤 놀이를 좋아하는지는 자료에만 있어요.","가장 많은 놀이, 더 적은 놀이는 그래프로 알 수 있어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#6','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'ox','auto','제기차기를 가장 많이 한 모둠은 4모둠이고, 그래프에서 ◯가 가장 높이 쌓여 있어요.',ARRAY['M2-2-u5-X07']::text[],false,'{"seq":6,"concept":"M2-2-u5-C7","difficulty":3,"kind":"ox","stem":"제기차기를 가장 많이 한 모둠은 4모둠이고, 그래프에서 ◯가 가장 높이 쌓여 있어요.","answer":"O","reason_options":[{"t":"4모둠이 13회로 가장 많아서 ◯도 13개로 가장 높으니까","correct":true},{"t":"4모둠이 가운데 있어서 가장 높아 보이니까","mis":"M2-2-u5-X07"}],"mis":"M2-2-u5-X07","explanation":["4모둠은 13회로 가장 많아요.","그래서 그래프에서 ◯가 13개로 가장 높이 쌓여 있어요.","높이는 자리가 아니라 수로 정해져요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#7','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',3,'mc','auto','가장 많은 학생이 받고 싶은 선물은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":7,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"가장 많은 학생이 받고 싶은 선물은 무엇인가요?","explanation":["표에서 수가 가장 큰 칸을 찾아요.","로봇 5명, 인형 3명, 모자 4명, 신발 4명, 그림책 4명이에요 — 가장 많은 것은 로봇(5명)이에요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most"}},"options":[{"t":"로봇","correct":true},{"t":"인형","mis":"M2-2-u5-X09"},{"t":"모자","mis":"M2-2-u5-X07"},{"t":"신발","mis":"M2-2-u5-X07"}],"asset":{"type":"ftable","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#8','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'essay','teacher','표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 표는 투호 놀이가 8명이라는 것처럼 항목별 수와 합계 22명을 바로 읽기에 편리하다. 그래프는 공기놀이가 가장 높이 쌓여 가장 많다는 것처럼 어느 것이 많고 적은지 한눈에 견주기에 편리하다.","scoring_points":["표가 수·합계를 읽기 좋음을 썼는가","그래프가 많고 적음을 견주기 좋음을 썼는가","예를 들었는가"]},"explanation":["표는 항목별 수와 합계를 바로 읽기 좋아요.","그래프는 많고 적음을 한눈에 견주기 좋아요.","예를 들어 설명하면 더 분명해요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#9','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'essay','teacher','「3명보다 많은 놀이」를 그래프에서 찾는 방법을 설명하고, 비사치기(3명)가 들어가는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"「3명보다 많은 놀이」를 그래프에서 찾는 방법을 설명하고, 비사치기(3명)가 들어가는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 3칸 자리에 선을 긋고 그 위에 ◯가 있는 놀이를 찾으면 투호 놀이(8명)와 공기놀이(9명)이다. 비사치기는 딱 3명이라 3명보다 많은 것이 아니므로 들어가지 않는다.","scoring_points":["3칸 위에 선을 긋는 방법을 썼는가","투호 놀이·공기놀이를 찾았는가","비사치기가 안 들어가는 까닭을 썼는가"]},"explanation":["3칸 자리에 선을 긋고 그 위를 봐요.","투호 놀이와 공기놀이가 3명보다 많아요.","딱 3명인 비사치기는 들어가지 않아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L05_challenge#10','math',2,2,'u5','L05','g2_2_math_u5_L05_challenge','lesson_challenge','M2-2-u5-C7',4,'mc','auto','공기놀이와 투호 놀이를 좋아하는 학생 수의 차이와 합을 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],false,'{"seq":10,"concept":"M2-2-u5-C7","difficulty":4,"kind":"mc","stem":"공기놀이와 투호 놀이를 좋아하는 학생 수의 차이와 합을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"1명, 17명","correct":true},{"t":"17명, 1명","mis":"M2-2-u5-X08"},{"t":"1명, 22명","mis":"M2-2-u5-X03"},{"t":"9명, 8명","mis":"M2-2-u5-X08"}],"explanation":["공기놀이 9명, 투호 놀이 8명이에요.","차이는 9 − 8 = 1명이에요.","합은 9 + 8 = 17명이에요 — 22명은 반 전체 합계예요."],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","total":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#1','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C8","difficulty":1,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["「보드게임」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"variant_rule":{"tg":{"ask":"tally"}},"answer":["6"],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,null,5],"unit":"명","vh":"학생 수","tally":[4,5,6,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#2','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'mc','auto','보드게임을 원하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":2,"concept":"M2-2-u5-C8","difficulty":1,"kind":"mc","stem":"보드게임을 원하는 학생은 몇 명인가요?","explanation":["그래프에서 「보드게임」 칸에 ◯가 몇 개 쌓였는지 세어요.","보드게임을 원하는 학생은 6명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"options":[{"t":"6명","correct":true},{"t":"7명","mis":"M2-2-u5-X01"},{"t":"5명","mis":"M2-2-u5-X01"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#3','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'sa','auto','표를 보고 그래프를 완성하려고 해요. 공기놀이 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C8","difficulty":1,"kind":"sa","stem":"표를 보고 그래프를 완성하려고 해요. 공기놀이 칸에는 ◯를 몇 개 그려야 하나요? 숫자로 쓰세요.","explanation":["표에서 공기놀이는 5명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 5개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"answer":["5","5개"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"blank":[1]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#4','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',1,'error','auto','민영이가 선생님께 쓴 쪽지: 「선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 ( )입니다.」 빈칸에 들어갈 놀이를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X07','M2-2-u5-X16']::text[],false,'{"seq":4,"concept":"M2-2-u5-C8","difficulty":1,"kind":"error","stem":"민영이가 선생님께 쓴 쪽지: 「선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 ( )입니다.」 빈칸에 들어갈 놀이를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「맨 앞에 있는 땅따먹기야.」","correct":true,"mis_target":"M2-2-u5-X07"},{"t":"가은 — 「◯가 가장 높은 보드게임이야.」","mis":"M2-2-u5-X16"},{"t":"태오 — 「표에서 6명으로 가장 많은 보드게임이야.」","mis":"M2-2-u5-X16"}],"explanation":["가장 많은 놀이는 수가 가장 큰 보드게임(6명)이에요.","맨 앞 칸이라고 가장 많은 게 아니에요.","땅따먹기는 4명으로 가장 적어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#5','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'mc','auto','가장 적은 학생이 원하는 교실 놀이는 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":5,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"가장 적은 학생이 원하는 교실 놀이는 무엇인가요?","explanation":["그래프에서 ◯가 가장 낮게(짧게) 쌓인 칸을 찾아요.","땅따먹기 4명, 공기놀이 5명, 보드게임 6명, 딱지치기 5명이에요 — 가장 적은 것은 땅따먹기(4명)예요.","「가장 적은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"least","src":"graph"}},"options":[{"t":"땅따먹기","correct":true},{"t":"보드게임","mis":"M2-2-u5-X09"},{"t":"공기놀이","mis":"M2-2-u5-X07"},{"t":"딱지치기","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#6','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'sa','auto','공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u5-C8","difficulty":2,"kind":"sa","stem":"공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요? 숫자로 쓰세요.","explanation":["공기놀이를 원하는 학생은 5명, 딱지치기를 원하는 학생은 5명이에요.","5 + 5 = 10이니 모두 10명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"answer":["10","10명"],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#7','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":7,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 땅따먹기는 4명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"땅따먹기 — 표는 4명인데 ◯를 5개 그렸다","correct":true},{"t":"공기놀이 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"보드게임 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"딱지치기 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"drawn":[5,5,6,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#8','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'ox','auto','조사해서 알게 된 것을 쪽지에 적을 때는 표와 그래프에서 알게 된 것을 그대로 적어요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":8,"concept":"M2-2-u5-C8","difficulty":2,"kind":"ox","stem":"조사해서 알게 된 것을 쪽지에 적을 때는 표와 그래프에서 알게 된 것을 그대로 적어요.","answer":"O","reason_options":[{"t":"내 마음대로 바꾸어 적으면 조사한 것이 아니니까","correct":true},{"t":"쪽지는 내가 바라는 놀이를 적는 것이니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["쪽지에는 조사해서 알게 된 것을 적어요.","표와 그래프에 나타난 대로 적어야 해요.","마음대로 바꾸면 조사한 결과가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#9','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',2,'match','auto','생일 선물 표를 보고 알맞은 것끼리 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C8","difficulty":2,"kind":"match","stem":"생일 선물 표를 보고 알맞은 것끼리 이으세요.","pairs":[{"l":"가장 많은 선물","r":"로봇 — 5명"},{"l":"가장 적은 선물","r":"인형 — 3명"},{"l":"수가 모두 같은 선물","r":"모자·신발·그림책 — 4명"}],"mis":"M2-2-u5-X07","explanation":["가장 많은 것은 로봇(5명)이에요.","가장 적은 것은 인형(3명)이에요.","모자·신발·그림책은 4명으로 같아요."],"asset":{"type":"ftable","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_basic#10','math',2,2,'u5','L06','g2_2_math_u5_L06_basic','lesson_basic','M2-2-u5-C8',3,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":10,"concept":"M2-2-u5-C8","difficulty":3,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 보드게임 6명이에요.","◯를 6개까지 쌓아야 하니 세로는 6칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"6칸","correct":true},{"t":"20칸","mis":"M2-2-u5-X12"},{"t":"4칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#1','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',2,'sa','auto','그림책을 받고 싶은 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C8","difficulty":2,"kind":"sa","stem":"그림책을 받고 싶은 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「그림책」 칸에 ×가 몇 개 쌓였는지 세어요.","그림책을 받고 싶은 학생은 4명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["4","4명"],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#2','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',2,'mc','auto','5명보다 많은 교실 놀이는 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":2,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"5명보다 많은 교실 놀이는 모두 몇 가지인가요?","explanation":["5명인 칸 위에 선을 긋고 그 위에 ◯가 있는 교실 놀이를 찾아요.","보드게임 — 1가지예요.","「5명보다 많은」에 딱 5명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"1가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"6가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#3','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',3,'sa','auto','보드게임을 원하는 학생은 땅따먹기를 원하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C8","difficulty":3,"kind":"sa","stem":"보드게임을 원하는 학생은 땅따먹기를 원하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["보드게임을 원하는 학생은 6명, 땅따먹기를 원하는 학생은 4명이에요.","6 − 4 = 2이니 2명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["2","2명"],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#4','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":4,"concept":"M2-2-u5-C8","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「공기놀이」 칸을 보세요.","◯가 위에서부터 채워져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","correct":true},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","bad":{"col":1,"how":"top"},"rows":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#5','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',3,'error','auto','조사한 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X16']::text[],false,'{"seq":5,"concept":"M2-2-u5-C8","difficulty":3,"kind":"error","stem":"조사한 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"지후 — 「우리 반 학생들은 모두 보드게임을 원합니다.」","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"민솔 — 「가장 많은 학생들이 원하는 교실 놀이는 보드게임입니다.」","mis":"M2-2-u5-X16"},{"t":"다온 — 「땅따먹기를 원하는 친구들이 가장 적습니다.」","mis":"M2-2-u5-X16"}],"explanation":["보드게임을 원하는 학생은 6명이지 모두가 아니에요.","표에 나타난 대로 「가장 많은」이라고 적어야 해요.","땅따먹기 4명이 가장 적다는 말은 맞아요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#6','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',3,'mc','auto','우리 반 20명이 교실 놀이를 조사했는데 표의 합계가 19였어요. 무엇을 해야 하나요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],false,'{"seq":6,"concept":"M2-2-u5-C8","difficulty":3,"kind":"mc","stem":"우리 반 20명이 교실 놀이를 조사했는데 표의 합계가 19였어요. 무엇을 해야 하나요?","options":[{"t":"빠진 친구가 있는지 다시 조사한다","correct":true},{"t":"합계를 20으로 고쳐 적는다","mis":"M2-2-u5-X15"},{"t":"그래프를 먼저 그린다","mis":"M2-2-u5-X15"},{"t":"가장 많은 놀이에 1을 더한다","mis":"M2-2-u5-X01"}],"explanation":["합계는 조사한 전체 수라 반 학생 수 20과 같아야 해요.","19면 한 명을 빠뜨린 거예요.","수를 마음대로 고치지 말고 다시 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#7','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',3,'ox','auto','표의 수와 그래프의 ◯ 수는 반드시 같아야 해요.',ARRAY['M2-2-u5-X11']::text[],false,'{"seq":7,"concept":"M2-2-u5-C8","difficulty":3,"kind":"ox","stem":"표의 수와 그래프의 ◯ 수는 반드시 같아야 해요.","answer":"O","reason_options":[{"t":"같은 자료를 표와 그래프 두 가지로 나타낸 것이니까","correct":true},{"t":"그래프는 대강 그려도 되니까","mis":"M2-2-u5-X11"}],"mis":"M2-2-u5-X11","explanation":["표와 그래프는 같은 자료를 나타낸 거예요.","그래서 보드게임이 표에서 6명이면 ◯도 6개예요.","하나라도 다르면 잘못 옮긴 거예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#8','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',4,'essay','teacher','우리 반이 원하는 교실 놀이를 조사해서 표와 그래프로 나타내려고 해요. 조사 → 표 → 그래프의 차례로 할 일을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"우리 반이 원하는 교실 놀이를 조사해서 표와 그래프로 나타내려고 해요. 조사 → 표 → 그래프의 차례로 할 일을 설명해 보세요.","answer_guide":{"answer":"예: 먼저 한 사람씩 원하는 놀이를 말하게 하고 ／ 표시를 하며 센다. 센 수를 놀이별로 적고 합계를 써서 표를 만들고, 합계가 반 학생 수와 같은지 확인한다. 그다음 가장 큰 수만큼 칸을 나누고 표의 수만큼 ◯를 맨 아래부터 채워 그래프를 그린다.","scoring_points":["조사 방법과 ／ 표시 세기를 썼는가","표에 수와 합계를 쓰고 확인함을 썼는가","칸 나누기와 맨 아래부터 채우기를 썼는가"]},"explanation":["조사하며 ／ 표시로 세어요.","놀이별 수와 합계를 표로 적고 반 학생 수와 견줘요.","가장 큰 수만큼 칸을 나누고 ◯를 맨 아래부터 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#9','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',4,'essay','teacher','표와 그래프를 보고 선생님께 알려 드릴 쪽지를 두 문장으로 써 보세요. (가장 많은 놀이와 가장 적은 놀이)','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"표와 그래프를 보고 선생님께 알려 드릴 쪽지를 두 문장으로 써 보세요. (가장 많은 놀이와 가장 적은 놀이)","answer_guide":{"answer":"예: 선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 보드게임(6명)이고, 땅따먹기(4명)를 원하는 친구들이 가장 적습니다.","scoring_points":["가장 많은 놀이(보드게임)를 바르게 썼는가","가장 적은 놀이(땅따먹기)를 바르게 썼는가","조사한 결과 그대로 적었는가"]},"explanation":["가장 많은 놀이는 보드게임 6명이에요.","가장 적은 놀이는 땅따먹기 4명이에요.","알게 된 것을 그대로 적어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L06_challenge#10','math',2,2,'u5','L06','g2_2_math_u5_L06_challenge','lesson_challenge','M2-2-u5-C8',4,'mc','auto','생일 선물 표에서 로봇을 뺀 나머지 선물을 받고 싶은 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X04']::text[],false,'{"seq":10,"concept":"M2-2-u5-C8","difficulty":4,"kind":"mc","stem":"생일 선물 표에서 로봇을 뺀 나머지 선물을 받고 싶은 학생은 모두 몇 명인가요?","options":[{"t":"15명","correct":true},{"t":"5명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"4명","mis":"M2-2-u5-X04"}],"explanation":["로봇은 5명, 합계는 20명이에요.","20 − 5 = 15명이에요.","3 + 4 + 4 + 4 = 15로 세어도 같아요."],"asset":{"type":"ftable","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#1','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?","explanation":["자료에서 「놀이 한마당」을 고른 이름표만 ／ 표시를 하며 세어요.","놀이 한마당이 즐거웠던 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"act","items":[["다윤","현장체험학습"],["지은","현장체험학습"],["슬기","신나는 무용"],["연우","현장체험학습"],["우영","안전 체험"],["도현","놀이 한마당"],["소희","놀이 한마당"],["채원","놀이 한마당"],["지아","신나는 무용"],["정우","안전 체험"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#2','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C1',1,'sa','auto','텃밭 가꾸기가 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"텃밭 가꾸기가 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「텃밭 가꾸기」 칸 아래의 수를 읽어요.","텃밭 가꾸기가 즐거웠던 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["3","3명"],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#3','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C2',1,'mc','auto','슬기네 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":3,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"슬기네 반 학생은 모두 몇 명인가요?","explanation":["표의 각 활동별 수는 현장체험학습 7명, 안전 체험 3명, 놀이 한마당 5명, 신나는 무용 2명, 텃밭 가꾸기 3명이에요.","7 + 3 + 5 + 2 + 3 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"7명","mis":"M2-2-u5-X03"},{"t":"5명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#4','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C3',1,'mc','auto','자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"빠진 친구가 없도록 모두 조사한다","correct":true},{"t":"빨리 끝나도록 몇 명만 조사한다","mis":"M2-2-u5-X15"},{"t":"한 친구에게 두 번씩 물어본다","mis":"M2-2-u5-X01"}],"explanation":["조사는 빠진 사람이 없어야 해요.","몇 명만 조사하면 우리 반 결과가 아니에요.","두 번 물으면 두 번 세게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#5','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「가을」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u5-X06"},{"t":"7","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,null,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#6','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 개 6명이에요.","◯를 6개까지 쌓아야 하니 세로는 6칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"6칸","correct":true},{"t":"20칸","mis":"M2-2-u5-X12"},{"t":"5칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#7','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C6',1,'sa','auto','고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":1,"kind":"sa","stem":"고양이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「고양이」 칸에 ◯가 몇 개 쌓였는지 세어요.","고양이를 좋아하는 학생은 5명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["5","5명"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#8','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C7',1,'mc','auto','가장 많은 학생이 좋아하는 전통 놀이는 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"가장 많은 학생이 좋아하는 전통 놀이는 무엇인가요?","explanation":["그래프에서 ◯가 가장 높이(길게) 쌓인 칸을 찾아요.","비사치기 3명, 투호 놀이 8명, 제기차기 2명, 공기놀이 9명이에요 — 가장 많은 것은 공기놀이(9명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most","src":"graph"}},"options":[{"t":"공기놀이","correct":true},{"t":"제기차기","mis":"M2-2-u5-X09"},{"t":"비사치기","mis":"M2-2-u5-X07"},{"t":"투호 놀이","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#9','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C2',2,'mc','auto','안전 체험이 즐거웠던 학생과 텃밭 가꾸기가 즐거웠던 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"안전 체험이 즐거웠던 학생과 텃밭 가꾸기가 즐거웠던 학생은 모두 몇 명인가요?","explanation":["안전 체험이 즐거웠던 학생은 3명, 텃밭 가꾸기가 즐거웠던 학생은 3명이에요.","3 + 3 = 6이니 모두 6명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"6명","correct":true},{"t":"0명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#10','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 7 + 6 + 3 = 16이에요.","16 + □ = 20이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["4"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,null,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#11','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C6',2,'mc','auto','표를 보고 그래프를 완성하려고 해요. 금붕어 칸에는 ◯를 몇 개 그려야 하나요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":11,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"표를 보고 그래프를 완성하려고 해요. 금붕어 칸에는 ◯를 몇 개 그려야 하나요?","explanation":["표에서 금붕어는 4명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 4개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"options":[{"t":"4개","correct":true},{"t":"5개","mis":"M2-2-u5-X11"},{"t":"3개","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"blank":[4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#12','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C7',2,'sa','auto','공기놀이를 좋아하는 학생은 비사치기를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"공기놀이를 좋아하는 학생은 비사치기를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["공기놀이를 좋아하는 학생은 9명, 비사치기를 좋아하는 학생은 3명이에요.","9 − 3 = 6이니 6명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["6","6명"],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#13','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":13,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 보드게임은 6명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"보드게임 — 표는 6명인데 ◯를 5개 그렸다","correct":true},{"t":"땅따먹기 — 표는 4명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"},{"t":"공기놀이 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"딱지치기 — 표는 5명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"drawn":[4,5,5,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#14','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C3',2,'ox','auto','조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":14,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.","answer":"O","reason_options":[{"t":"말하기·손 들기·이름 붙이기 가운데 조사할 것에 맞는 방법을 고르니까","correct":true},{"t":"조사 방법은 언제나 한 가지뿐이니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["조사 방법에는 여러 가지가 있어요.","무엇을 조사하느냐에 따라 알맞은 방법이 달라요.","어떤 방법이든 빠진 친구가 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#15','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C5',2,'mc','auto','그래프를 그릴 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X15']::text[],false,'{"seq":15,"concept":"M2-2-u5-C5","difficulty":2,"kind":"mc","stem":"그래프를 그릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"가로와 세로에 무엇을 나타낼지 정한다","correct":true},{"t":"◯를 맨 위부터 그린다","mis":"M2-2-u5-X10"},{"t":"합계를 쓴다","mis":"M2-2-u5-X15"}],"explanation":["먼저 가로와 세로에 무엇을 나타낼지 정해요.","그다음 가장 큰 수만큼 칸을 나누어요.","◯는 맨 아래부터 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#16','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C1',2,'ox','auto','표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":16,"concept":"M2-2-u5-C1","difficulty":2,"kind":"ox","stem":"표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.","answer":"X","reason_options":[{"t":"표에는 활동별 학생 수만 있고 누가 골랐는지는 없으니까","correct":true},{"t":"표에는 조사한 것이 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"mis":"M2-2-u5-X16","explanation":["표에는 활동별 학생 수와 합계만 있어요.","누가 무엇을 골랐는지는 자료를 봐야 알아요.","표는 수를 한눈에 알기 좋아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#17','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C7',3,'mc','auto','3명보다 많은 전통 놀이는 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":17,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"3명보다 많은 전통 놀이는 모두 몇 가지인가요?","explanation":["3명인 칸 위에 선을 긋고 그 위에 ◯가 있는 전통 놀이를 찾아요.","투호 놀이, 공기놀이 — 2가지예요.","「3명보다 많은」에 딱 3명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"2가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"17가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#18','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C6',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":18,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「개」 칸을 보세요.","◯가 위에서부터 채워져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","correct":true},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이"],"counts":[6,3,5],"unit":"명","vh":"학생 수","bad":{"col":0,"how":"top"},"rows":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#19','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C8',3,'error','auto','조사한 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X16']::text[],false,'{"seq":19,"concept":"M2-2-u5-C8","difficulty":3,"kind":"error","stem":"조사한 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"지후 — 「우리 반 학생들은 모두 보드게임을 원합니다.」","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"민솔 — 「가장 많은 학생들이 원하는 교실 놀이는 보드게임입니다.」","mis":"M2-2-u5-X16"},{"t":"다온 — 「땅따먹기를 원하는 친구들이 가장 적습니다.」","mis":"M2-2-u5-X16"}],"explanation":["보드게임을 원하는 학생은 6명이지 모두가 아니에요.","표에 나타난 대로 「가장 많은」이라고 적어요.","땅따먹기가 가장 적다는 말은 맞아요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#20','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C2',3,'mc','auto','현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":20,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?","options":[{"t":"13명","correct":true},{"t":"7명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"12명","mis":"M2-2-u5-X01"}],"explanation":["현장체험학습이 아닌 활동은 네 가지예요.","3 + 5 + 2 + 3 = 13이에요.","합계 20에서 7을 빼도 13이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#21','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C4',3,'error','auto','친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":21,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"윤슬 — 조사한 친구가 적어서 합계를 25로 늘려 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"가은 — 제목을 「우리 반 친구들이 태어난 계절별 학생 수」라고 썼다","mis":"M2-2-u5-X15"},{"t":"태오 — 7 + 4 + 6 + 3을 더해 합계 20을 썼다","mis":"M2-2-u5-X15"}],"explanation":["합계는 항목별 수를 더한 그대로 적어요.","마음대로 늘려 쓰면 조사한 것이 아니에요.","제목과 합계를 쓴 것은 바르게 만든 거예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#22','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C5',3,'ox','auto','가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":22,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"가장 많은 수가 6명이면 세로를 10칸으로 나누어야 해요.","answer":"X","reason_options":[{"t":"가장 큰 수 6만큼 6칸이면 되고 더 나누면 빈 칸이 남으니까","correct":true},{"t":"칸은 많을수록 좋으니까","mis":"M2-2-u5-X12"}],"mis":"M2-2-u5-X12","explanation":["세로 칸 수는 가장 큰 수만큼이면 돼요.","6명이면 6칸이에요.","10칸이면 빈 칸이 많이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#23','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C7',4,'essay','teacher','표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"표와 그래프는 각각 어떤 것을 알기에 편리한지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 표는 투호 놀이가 8명이라는 것처럼 항목별 수와 합계 22명을 바로 읽기에 편리하다. 그래프는 공기놀이가 가장 높이 쌓여 가장 많다는 것처럼 많고 적음을 한눈에 견주기에 편리하다.","scoring_points":["표가 수·합계를 읽기 좋음을 썼는가","그래프가 많고 적음을 견주기 좋음을 썼는가","예를 들었는가"]},"explanation":["표는 수와 합계를 바로 읽기 좋아요.","그래프는 많고 적음을 한눈에 견주기 좋아요.","예를 들면 더 분명해요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#24','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C8',4,'essay','teacher','우리 반이 원하는 교실 놀이를 조사해서 표와 그래프로 나타내려고 해요. 조사 → 표 → 그래프의 차례로 할 일을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"우리 반이 원하는 교실 놀이를 조사해서 표와 그래프로 나타내려고 해요. 조사 → 표 → 그래프의 차례로 할 일을 설명해 보세요.","answer_guide":{"answer":"예: 한 사람씩 원하는 놀이를 말하게 하고 ／ 표시를 하며 센다. 센 수를 놀이별로 적고 합계를 써서 표를 만들고 합계가 반 학생 수와 같은지 확인한다. 가장 큰 수만큼 칸을 나누고 표의 수만큼 ◯를 맨 아래부터 채워 그래프를 그린다.","scoring_points":["조사 방법과 ／ 표시 세기를 썼는가","표에 수와 합계를 쓰고 확인함을 썼는가","칸 나누기와 맨 아래부터 채우기를 썼는가"]},"explanation":["조사하며 ／ 표시로 세어요.","놀이별 수와 합계를 표로 적고 반 학생 수와 견줘요.","가장 큰 수만큼 칸을 나누고 ◯를 맨 아래부터 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_a#25','math',2,2,'u5','','g2_2_math_u5_review_a','unit_review','M2-2-u5-C3',4,'essay','teacher','친구들이 좋아하는 과일을 조사하려고 해요. 어떤 방법으로 조사할지 정하고, 빠뜨리지 않고 조사하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"친구들이 좋아하는 과일을 조사하려고 해요. 어떤 방법으로 조사할지 정하고, 빠뜨리지 않고 조사하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 한 사람씩 차례로 좋아하는 과일을 말하게 하고 말한 친구의 이름을 과일 칸에 적어 둔다. 다 끝나면 이름 수를 세어 반 학생 수와 같은지 확인한다.","scoring_points":["조사 방법을 하나 정했는가","조사한 친구를 표시하는 방법을 썼는가","전체 수와 견주어 확인함을 썼는가"]},"explanation":["조사 방법을 하나 정해요.","조사한 친구를 적어 두면 빠뜨리지 않아요.","다 세고 반 학생 수와 같은지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#1','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 봄에 태어난 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 봄에 태어난 학생은 몇 명인가요?","explanation":["자료에서 「봄」을 고른 이름표만 ／ 표시를 하며 세어요.","봄에 태어난 학생은 4명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"4명","correct":true},{"t":"5명","mis":"M2-2-u5-X01"},{"t":"3명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"season","items":[["다윤","여름"],["지은","겨울"],["슬기","봄"],["연우","봄"],["우영","봄"],["도현","겨울"],["소희","가을"],["채원","가을"],["지아","가을"],["정우","봄"],["세미","여름"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#2','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C1',1,'sa','auto','겨울에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"겨울에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「겨울」 칸 아래의 수를 읽어요.","겨울에 태어난 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["3","3명"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#3','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C2',1,'mc','auto','우리 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":3,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"우리 반 학생은 모두 몇 명인가요?","explanation":["표의 각 계절별 수는 봄 7명, 여름 4명, 가을 6명, 겨울 3명이에요.","7 + 4 + 6 + 3 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"7명","mis":"M2-2-u5-X03"},{"t":"4명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#4','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C3',1,'mc','auto','조사하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"조사하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 친구에게만 물어본다","correct":true},{"t":"한 사람씩 차례로 말한다","mis":"M2-2-u5-X15"},{"t":"계절별로 손을 들어 센다","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","말하기와 손 들기는 알맞은 방법이에요.","몇 명만 고르면 빠진 친구가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#5','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「팥」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"7","correct":true},{"t":"6","mis":"M2-2-u5-X06"},{"t":"8","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[null,5,2,3,4],"unit":"명","vh":"학생 수","tally":[7,5,2,3,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#6','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 공기놀이 9명이에요.","◯를 9개까지 쌓아야 하니 세로는 9칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"9칸","correct":true},{"t":"22칸","mis":"M2-2-u5-X12"},{"t":"4칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#7','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C6',1,'sa','auto','투호 놀이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":1,"kind":"sa","stem":"투호 놀이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「투호 놀이」 칸에 ◯가 몇 개 쌓였는지 세어요.","투호 놀이를 좋아하는 학생은 8명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["8","8명"],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#8','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C7',1,'mc','auto','가장 많은 학생이 좋아하는 동물은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"가장 많은 학생이 좋아하는 동물은 무엇인가요?","explanation":["그래프에서 ◯가 가장 높이(길게) 쌓인 칸을 찾아요.","개 6명, 앵무새 3명, 고양이 5명, 토끼 2명, 금붕어 4명이에요 — 가장 많은 것은 개(6명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most","src":"graph"}},"options":[{"t":"개","correct":true},{"t":"토끼","mis":"M2-2-u5-X09"},{"t":"앵무새","mis":"M2-2-u5-X07"},{"t":"고양이","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#9','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C2',2,'mc','auto','봄에 태어난 학생과 가을에 태어난 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"봄에 태어난 학생과 가을에 태어난 학생은 모두 몇 명인가요?","explanation":["봄에 태어난 학생은 7명, 가을에 태어난 학생은 6명이에요.","7 + 6 = 13이니 모두 13명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"13명","correct":true},{"t":"1명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#10','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 3 + 5 + 2 + 4 = 14예요.","14 + □ = 18이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["4"],"asset":{"type":"ftable","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감","복숭아"],"counts":[3,5,2,null,4],"unit":"명","vh":"학생 수","total":18}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#11','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C6',2,'mc','auto','표를 보고 그래프를 완성하려고 해요. 보드게임 칸에는 ◯를 몇 개 그려야 하나요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":11,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"표를 보고 그래프를 완성하려고 해요. 보드게임 칸에는 ◯를 몇 개 그려야 하나요?","explanation":["표에서 보드게임은 6명이에요.","그래프의 수는 표의 수와 같아야 해요 — ◯를 6개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"options":[{"t":"6개","correct":true},{"t":"7개","mis":"M2-2-u5-X11"},{"t":"5개","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true,"blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#12','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C7',2,'sa','auto','4모둠의 제기차기 횟수는 3모둠의 제기차기 횟수보다 몇 회 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"4모둠의 제기차기 횟수는 3모둠의 제기차기 횟수보다 몇 회 더 많은가요? 숫자로 쓰세요.","explanation":["4모둠의 제기차기 횟수는 13회, 3모둠의 제기차기 횟수는 7회예요.","13 − 7 = 6이니 6회 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["6","6회"],"asset":{"type":"ftable","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#13','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":13,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 개는 6명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"개 — 표는 6명인데 ◯를 5개 그렸다","correct":true},{"t":"앵무새 — 표는 3명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"고양이 — 표는 5명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"토끼 — 표는 2명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","table":true,"drawn":[5,3,5,2,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#14','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C3',2,'ox','auto','반 친구 가운데 몇 명만 조사해도 우리 반의 결과를 알 수 있어요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":14,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"반 친구 가운데 몇 명만 조사해도 우리 반의 결과를 알 수 있어요.","answer":"X","reason_options":[{"t":"빠진 친구가 있으면 우리 반 전체의 결과가 아니니까","correct":true},{"t":"몇 명만 봐도 다 비슷하니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["조사는 반 친구 모두에게 해야 해요.","몇 명만 조사하면 빠진 친구의 생각은 모르는 거예요.","그래서 우리 반의 결과라고 할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#15','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C5',2,'mc','auto','가장 많은 수가 9명인 자료를 그래프로 그리려면 세로를 몇 칸으로 나누면 되나요?',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":15,"concept":"M2-2-u5-C5","difficulty":2,"kind":"mc","stem":"가장 많은 수가 9명인 자료를 그래프로 그리려면 세로를 몇 칸으로 나누면 되나요?","options":[{"t":"9칸","correct":true},{"t":"22칸","mis":"M2-2-u5-X12"},{"t":"4칸","mis":"M2-2-u5-X12"}],"explanation":["세로 칸 수는 가장 큰 수만큼이에요.","가장 큰 수가 9명이니 9칸이에요.","22는 합계, 4는 항목 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#16','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C1',2,'ox','auto','분류할 때의 항목과 표의 항목은 같아요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":16,"concept":"M2-2-u5-C1","difficulty":2,"kind":"ox","stem":"분류할 때의 항목과 표의 항목은 같아요.","answer":"O","reason_options":[{"t":"분류한 칸의 이름을 그대로 세어서 표에 적으니까","correct":true},{"t":"표에는 항목을 새로 정하니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["분류한 칸의 이름이 곧 표의 항목이에요.","칸마다 세어서 수로 적은 것이 표예요.","그래서 항목은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#17','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C7',3,'mc','auto','4명보다 많은 간식은 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":17,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"4명보다 많은 간식은 모두 몇 가지인가요?","explanation":["4명인 칸 위에 선을 긋고 그 위에 ◯가 있는 간식을 찾아요.","햄버거, 떡볶이 — 2가지예요.","「4명보다 많은」에 딱 4명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"2가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"13가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"snack","title":"우리 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#18','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C6',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":18,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「보드게임」 칸을 보세요.","◯가 중간 한 칸을 비우고 그 다음 칸에 그려져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"중간 칸을 건너뛰고 그렸다","correct":true},{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","bad":{"col":2,"how":"skip"},"rows":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#19','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C8',3,'error','auto','12월 날씨 표를 보고 쪽지를 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X16']::text[],false,'{"seq":19,"concept":"M2-2-u5-C8","difficulty":3,"kind":"error","stem":"12월 날씨 표를 보고 쪽지를 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"하람 — 「12월에는 비가 온 날이 가장 많았습니다.」","correct":true,"mis_target":"M2-2-u5-X09"},{"t":"윤슬 — 「12월에는 흐린 날이 11일로 가장 많았습니다.」","mis":"M2-2-u5-X16"},{"t":"채윤 — 「눈이 온 날은 5일로 가장 적었습니다.」","mis":"M2-2-u5-X16"}],"explanation":["흐린 날이 11일로 가장 많아요.","비가 온 날은 7일이에요.","표의 수를 보고 그대로 적어야 해요."],"asset":{"type":"ftable","topic":"weather","title":"12월 날씨별 일수","head":"날씨","cols":["맑음","흐림","비","눈"],"counts":[8,11,7,5],"unit":"일","vh":"일수","total":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#20','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C2',3,'mc','auto','봄에 태어나지 않은 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":20,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"봄에 태어나지 않은 학생은 모두 몇 명인가요?","options":[{"t":"13명","correct":true},{"t":"7명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"14명","mis":"M2-2-u5-X01"}],"explanation":["봄이 아닌 계절은 여름·가을·겨울이에요.","4 + 6 + 3 = 13이에요.","합계 20에서 봄 7명을 빼도 13이에요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#21','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C4',3,'error','auto','친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":21,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"도윤 — 제목 없이 수만 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 계절 칸을 봄·여름·가을·겨울로 나누어 적었다","mis":"M2-2-u5-X15"},{"t":"서아 — 합계 칸에 20을 적었다","mis":"M2-2-u5-X15"}],"explanation":["표에는 제목을 써야 해요.","항목을 나누고 합계를 쓴 것은 바르게 만든 거예요.","제목·항목·수·합계를 다 갖추어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#22','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C5',3,'ox','auto','표의 합계가 22명이면 그래프의 세로는 22칸으로 나누어야 해요.',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":22,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"표의 합계가 22명이면 그래프의 세로는 22칸으로 나누어야 해요.","answer":"X","reason_options":[{"t":"칸 수는 합계가 아니라 가장 큰 수만큼이면 되니까","correct":true},{"t":"합계만큼 칸이 있어야 다 그릴 수 있으니까","mis":"M2-2-u5-X12"}],"mis":"M2-2-u5-X12","explanation":["그래프는 항목마다 따로 쌓아요.","가장 큰 수만큼만 칸이 있으면 다 그릴 수 있어요.","합계 22칸은 너무 많아서 빈 칸이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#23','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C7',4,'essay','teacher','「3명보다 많은 놀이」를 그래프에서 찾는 방법을 설명하고, 비사치기(3명)가 들어가는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"「3명보다 많은 놀이」를 그래프에서 찾는 방법을 설명하고, 비사치기(3명)가 들어가는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 3칸 자리에 선을 긋고 그 위에 ◯가 있는 놀이를 찾으면 투호 놀이와 공기놀이이다. 비사치기는 딱 3명이라 3명보다 많은 것이 아니므로 들어가지 않는다.","scoring_points":["3칸 위에 선을 긋는 방법을 썼는가","투호 놀이·공기놀이를 찾았는가","비사치기가 안 들어가는 까닭을 썼는가"]},"explanation":["3칸 자리에 선을 긋고 그 위를 봐요.","투호 놀이와 공기놀이가 3명보다 많아요.","딱 3명인 비사치기는 들어가지 않아요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#24','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C8',4,'essay','teacher','표와 그래프를 보고 선생님께 알려 드릴 쪽지를 두 문장으로 써 보세요. (가장 많은 놀이와 가장 적은 놀이)','{}'::text[],false,'{"seq":24,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"표와 그래프를 보고 선생님께 알려 드릴 쪽지를 두 문장으로 써 보세요. (가장 많은 놀이와 가장 적은 놀이)","answer_guide":{"answer":"예: 선생님, 우리 반 학생들이 원하는 교실 놀이를 조사하였습니다. 가장 많은 학생들이 원하는 교실 놀이는 보드게임이고, 땅따먹기를 원하는 친구들이 가장 적습니다.","scoring_points":["가장 많은 놀이(보드게임)를 바르게 썼는가","가장 적은 놀이(땅따먹기)를 바르게 썼는가","조사한 결과 그대로 적었는가"]},"explanation":["가장 많은 놀이는 보드게임 6명이에요.","가장 적은 놀이는 땅따먹기 4명이에요.","알게 된 것을 그대로 적어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_b#25','math',2,2,'u5','','g2_2_math_u5_review_b','unit_review','M2-2-u5-C3',4,'essay','teacher','태어난 계절을 조사할 때 「계절별로 손 들기」와 「한 사람씩 말하기」 가운데 하나를 고르고, 그 방법의 좋은 점과 조심할 점을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"태어난 계절을 조사할 때 「계절별로 손 들기」와 「한 사람씩 말하기」 가운데 하나를 고르고, 그 방법의 좋은 점과 조심할 점을 설명해 보세요.","answer_guide":{"answer":"예: 손 들기를 고르면 한 번에 계절별로 셀 수 있어 빠르다. 다만 손을 안 든 친구나 두 번 든 친구가 없도록 네 계절의 수를 더해 반 학생 수와 같은지 확인해야 한다.","scoring_points":["방법을 하나 골랐는가","좋은 점을 썼는가","빠짐·두 번 세기를 막는 조심할 점을 썼는가"]},"explanation":["어느 방법이든 좋은 점이 있어요.","손 들기는 빠르고, 말하기는 차례가 분명해요.","빠진 친구가 없게 합계로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#1','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 고양이를 좋아하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 고양이를 좋아하는 학생은 몇 명인가요?","explanation":["자료에서 「고양이」를 고른 이름표만 ／ 표시를 하며 세어요.","고양이를 좋아하는 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"animal","items":[["다윤","금붕어"],["지은","개"],["슬기","개"],["연우","고양이"],["우영","금붕어"],["도현","개"],["소희","고양이"],["채원","토끼"],["지아","토끼"],["정우","금붕어"],["세미","개"],["수찬","고양이"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#2','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C1',1,'sa','auto','금붕어를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"금붕어를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「금붕어」 칸 아래의 수를 읽어요.","금붕어를 좋아하는 학생은 4명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["4","4명"],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#3','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C2',1,'mc','auto','수찬이네 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":3,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"수찬이네 반 학생은 모두 몇 명인가요?","explanation":["표의 각 동물별 수는 개 6명, 앵무새 3명, 고양이 5명, 토끼 2명, 금붕어 4명이에요.","6 + 3 + 5 + 2 + 4 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"6명","mis":"M2-2-u5-X03"},{"t":"5명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#4','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C3',1,'mc','auto','친구들이 태어난 계절을 조사하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"친구들이 태어난 계절을 조사하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"계절별로 손을 들게 하고 센다","correct":true},{"t":"내가 생각나는 대로 적는다","mis":"M2-2-u5-X15"},{"t":"한 명만 물어보고 다 같다고 적는다","mis":"M2-2-u5-X15"}],"explanation":["손을 들게 하면 계절별로 셀 수 있어요.","생각나는 대로 적으면 조사가 아니에요.","한 명만 물으면 나머지는 모르는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#5','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「보드게임」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u5-X06"},{"t":"7","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,null,5],"unit":"명","vh":"학생 수","tally":[4,5,6,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#6','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 가로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 보드게임 6명이에요.","◯를 6개까지 쌓아야 하니 가로는 6칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"6칸","correct":true},{"t":"20칸","mis":"M2-2-u5-X12"},{"t":"4칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#7','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C6',1,'sa','auto','딱지치기를 원하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":1,"kind":"sa","stem":"딱지치기를 원하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「딱지치기」 칸에 ×가 몇 개 쌓였는지 세어요.","딱지치기를 원하는 학생은 5명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["5","5명"],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#8','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C7',1,'mc','auto','가장 많은 학생이 좋아하는 간식은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"가장 많은 학생이 좋아하는 간식은 무엇인가요?","explanation":["그래프에서 ◯가 가장 높이(길게) 쌓인 칸을 찾아요.","햄버거 5명, 떡볶이 8명, 김밥 4명, 라면 2명이에요 — 가장 많은 것은 떡볶이(8명)예요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most","src":"graph"}},"options":[{"t":"떡볶이","correct":true},{"t":"라면","mis":"M2-2-u5-X09"},{"t":"햄버거","mis":"M2-2-u5-X07"},{"t":"김밥","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"snack","title":"우리 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#9','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C2',2,'mc','auto','개를 좋아하는 학생과 고양이를 좋아하는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"개를 좋아하는 학생과 고양이를 좋아하는 학생은 모두 몇 명인가요?","explanation":["개를 좋아하는 학생은 6명, 고양이를 좋아하는 학생은 5명이에요.","6 + 5 = 11이니 모두 11명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"11명","correct":true},{"t":"1명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#10','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 3 + 4 + 4 + 4 = 15예요.","15 + □ = 20이니 □ = 5예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["5"],"asset":{"type":"ftable","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[null,3,4,4,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#11','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C6',2,'mc','auto','표를 보고 그래프를 완성하려고 해요. 인형 칸에는 ×를 몇 개 그려야 하나요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":11,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"표를 보고 그래프를 완성하려고 해요. 인형 칸에는 ×를 몇 개 그려야 하나요?","explanation":["표에서 인형은 3명이에요.","그래프의 수는 표의 수와 같아야 해요 — ×를 3개 그려요.","맨 왼쪽 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"options":[{"t":"3개","correct":true},{"t":"4개","mis":"M2-2-u5-X11"},{"t":"2개","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"×","dir":"h","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수","table":true,"blank":[1]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#12','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C7',2,'sa','auto','떡볶이를 좋아하는 학생은 햄버거를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"떡볶이를 좋아하는 학생은 햄버거를 좋아하는 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["떡볶이를 좋아하는 학생은 8명, 햄버거를 좋아하는 학생은 5명이에요.","8 − 5 = 3이니 3명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["3","3명"],"asset":{"type":"ftable","topic":"snack","title":"우리 반 학생들이 좋아하는 간식별 학생 수","head":"간식","cols":["햄버거","떡볶이","김밥","라면"],"counts":[5,8,4,2],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#13','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":13,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 신발은 4명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"신발 — 표는 4명인데 ◯를 5개 그렸다","correct":true},{"t":"로봇 — 표는 5명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"인형 — 표는 3명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"},{"t":"모자 — 표는 4명인데 ◯를 3개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"gift","title":"받고 싶은 생일 선물별 학생 수","head":"선물","cols":["로봇","인형","모자","신발","그림책"],"counts":[5,3,4,4,4],"unit":"명","vh":"학생 수","table":true,"drawn":[5,3,4,5,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#14','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C3',2,'ox','auto','한 사람씩 차례로 말하게 하면 차례가 분명해서 빠뜨리기 어려워요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":14,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"한 사람씩 차례로 말하게 하면 차례가 분명해서 빠뜨리기 어려워요.","answer":"O","reason_options":[{"t":"누가 말했고 안 했는지 바로 알 수 있으니까","correct":true},{"t":"말하는 소리가 커서 잘 들리니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["한 사람씩 말하면 차례가 분명해요.","그래서 누가 아직 안 말했는지 알 수 있어요.","말한 친구의 이름을 적어 두면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#15','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C5',2,'mc','auto','가로와 세로를 바꾸어 그래프를 그리면 무엇이 달라지나요?',ARRAY['M2-2-u5-X13']::text[],false,'{"seq":15,"concept":"M2-2-u5-C5","difficulty":2,"kind":"mc","stem":"가로와 세로를 바꾸어 그래프를 그리면 무엇이 달라지나요?","options":[{"t":"자리와 기호","correct":true},{"t":"동물별 학생 수","mis":"M2-2-u5-X13"},{"t":"동물의 종류","mis":"M2-2-u5-X13"}],"explanation":["가로와 세로를 바꾸어 그려도 돼요.","동물 종류와 학생 수는 그대로예요.","◯를 쌓는 자리와 쓰는 기호만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#16','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C1',2,'ox','auto','센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":16,"concept":"M2-2-u5-C1","difficulty":2,"kind":"ox","stem":"센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.","answer":"O","reason_options":[{"t":"센 것과 아직 안 센 것이 구분되니까","correct":true},{"t":"표시를 하면 수가 늘어나니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["센 낱장에 표시를 하면 어디까지 셌는지 보여요.","그래서 빠뜨리거나 두 번 세지 않아요.","표시는 수를 바꾸지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#17','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C7',3,'mc','auto','5명보다 많은 교실 놀이는 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":17,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"5명보다 많은 교실 놀이는 모두 몇 가지인가요?","explanation":["5명인 칸 위에 선을 긋고 그 위에 ◯가 있는 교실 놀이를 찾아요.","보드게임 — 1가지예요.","「5명보다 많은」에 딱 5명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"1가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"6가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#18','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C6',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10']::text[],true,'{"seq":18,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「줄넘기」 칸을 보세요.","◯와 다른 기호가 섞여 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"기호를 섞어서 그렸다","correct":true},{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","mis":"M2-2-u5-X10"},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"sport","title":"우리 반 학생들이 좋아하는 운동별 학생 수","head":"운동","cols":["축구","줄넘기","달리기"],"counts":[5,4,3],"unit":"명","vh":"학생 수","bad":{"col":1,"how":"mix"},"rows":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#19','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C8',3,'error','auto','동물 조사 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X16']::text[],false,'{"seq":19,"concept":"M2-2-u5-C8","difficulty":3,"kind":"error","stem":"동물 조사 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"예준 — 「토끼를 좋아하는 학생이 가장 많습니다.」","correct":true,"mis_target":"M2-2-u5-X09"},{"t":"가은 — 「개를 좋아하는 학생이 6명으로 가장 많습니다.」","mis":"M2-2-u5-X16"},{"t":"태오 — 「토끼를 좋아하는 학생이 2명으로 가장 적습니다.」","mis":"M2-2-u5-X16"}],"explanation":["개가 6명으로 가장 많아요.","토끼는 2명으로 가장 적어요.","가장 많은 것과 적은 것을 바꾸어 적으면 안 돼요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#20','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C2',3,'mc','auto','개를 좋아하지 않는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":20,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"개를 좋아하지 않는 학생은 모두 몇 명인가요?","options":[{"t":"14명","correct":true},{"t":"6명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"13명","mis":"M2-2-u5-X01"}],"explanation":["개가 아닌 동물은 앵무새·고양이·토끼·금붕어예요.","3 + 5 + 2 + 4 = 14예요.","합계 20에서 개 6명을 빼도 14예요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#21','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C4',3,'error','auto','12월 날씨를 세어 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X15']::text[],false,'{"seq":21,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"12월 날씨를 세어 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"채윤 — 합계가 30인데 그대로 두었다","correct":true,"mis_target":"M2-2-u5-X01"},{"t":"하람 — 8 + 11 + 7 + 5 = 31이 12월의 날수와 같은지 확인했다","mis":"M2-2-u5-X15"},{"t":"예준 — 날씨별로 ／ 표시를 하며 세었다","mis":"M2-2-u5-X15"}],"explanation":["12월은 31일이라 합계가 31이어야 해요.","30이면 하루를 빠뜨린 거니 다시 세야 해요.","／ 표시를 하며 세고 합계로 확인한 것은 바른 방법이에요."],"asset":{"type":"ftable","topic":"weather","title":"12월 날씨별 일수","head":"날씨","cols":["맑음","흐림","비","눈"],"counts":[8,11,7,5],"unit":"일","vh":"일수","total":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#22','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C5',3,'ox','auto','가장 많은 수가 9명인데 세로를 5칸으로 나누면 다 그릴 수 없어요.',ARRAY['M2-2-u5-X12']::text[],false,'{"seq":22,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"가장 많은 수가 9명인데 세로를 5칸으로 나누면 다 그릴 수 없어요.","answer":"O","reason_options":[{"t":"9개를 쌓아야 하는데 칸이 5개뿐이니까","correct":true},{"t":"칸이 적으면 ◯가 작아지니까","mis":"M2-2-u5-X12"}],"mis":"M2-2-u5-X12","explanation":["9명이면 ◯를 9개 쌓아야 해요.","칸이 5개면 4개는 그릴 자리가 없어요.","칸은 가장 큰 수만큼 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#23','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C7',4,'essay','teacher','그래프를 보고 알 수 있는 것 두 가지와 알 수 없는 것 한 가지를 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"그래프를 보고 알 수 있는 것 두 가지와 알 수 없는 것 한 가지를 써 보세요.","answer_guide":{"answer":"예: 알 수 있는 것 — 개를 좋아하는 학생이 6명으로 가장 많다, 토끼를 좋아하는 학생이 2명으로 가장 적다. 알 수 없는 것 — 누가 어떤 동물을 좋아하는지.","scoring_points":["그래프로 알 수 있는 것을 두 가지 썼는가","누가 골랐는지는 알 수 없음을 썼는가","수를 바르게 읽었는가"]},"explanation":["그래프로 동물별 수와 많고 적음을 알 수 있어요.","가장 많은 것은 개, 가장 적은 것은 토끼예요.","누가 골랐는지는 자료에만 있어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#24','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C8',4,'essay','teacher','12월 날씨 표의 합계가 31이어야 하는 까닭을 쓰고, 합계가 31이 아니면 어떻게 해야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"12월 날씨 표의 합계가 31이어야 하는 까닭을 쓰고, 합계가 31이 아니면 어떻게 해야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 12월은 31일까지 있어서 날씨별 일수를 모두 더하면 31이 되어야 한다. 합계가 31이 아니면 어떤 날을 빠뜨리거나 두 번 센 것이므로 달력을 보고 ／ 표시를 하며 다시 센다.","scoring_points":["12월이 31일임을 썼는가","합계가 전체 날수와 같아야 함을 썼는가","다르면 다시 세어야 함을 썼는가"]},"explanation":["12월은 31일이에요.","날씨별 일수를 다 더하면 31이 되어야 해요.","다르면 빠뜨리거나 두 번 센 거니 다시 세요."],"asset":{"type":"ftable","topic":"weather","title":"12월 날씨별 일수","head":"날씨","cols":["맑음","흐림","비","눈"],"counts":[8,11,7,5],"unit":"일","vh":"일수","total":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_c#25','math',2,2,'u5','','g2_2_math_u5_review_c','unit_review','M2-2-u5-C3',4,'essay','teacher','우리 반 20명을 조사했는데 표의 합계가 21이 되었어요. 무엇이 잘못되었을지 쓰고 어떻게 해야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"우리 반 20명을 조사했는데 표의 합계가 21이 되었어요. 무엇이 잘못되었을지 쓰고 어떻게 해야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 합계는 조사한 전체 수라 20이어야 하는데 21이면 어떤 친구를 두 번 세었거나 ／ 표시를 잘못 센 것이다. 이름을 칸에 적어 두고 다시 세어서 합계가 20이 되게 고쳐야 한다.","scoring_points":["합계가 20이어야 함을 썼는가","두 번 센 것이 원인임을 썼는가","다시 세어 고쳐야 함을 썼는가"]},"explanation":["합계는 반 학생 수 20과 같아야 해요.","21이면 누군가를 두 번 센 거예요.","이름을 적어 두고 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#1','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 복숭아를 좋아하는 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 복숭아를 좋아하는 학생은 몇 명인가요?","explanation":["자료에서 「복숭아」를 고른 이름표만 ／ 표시를 하며 세어요.","복숭아를 좋아하는 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"fruit","items":[["다윤","복숭아"],["지은","포도"],["슬기","자두"],["연우","감"],["우영","복숭아"],["도현","자두"],["소희","포도"],["채원","감"],["지아","감"],["정우","복숭아"],["세미","포도"],["수찬","포도"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#2','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C1',1,'sa','auto','투호 놀이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"투호 놀이를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「투호 놀이」 칸 아래의 수를 읽어요.","투호 놀이를 좋아하는 학생은 8명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["8","8명"],"asset":{"type":"ftable","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#3','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C2',1,'mc','auto','우리 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":3,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"우리 반 학생은 모두 몇 명인가요?","explanation":["표의 각 교실 놀이별 수는 땅따먹기 4명, 공기놀이 5명, 보드게임 6명, 딱지치기 5명이에요.","4 + 5 + 6 + 5 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"6명","mis":"M2-2-u5-X03"},{"t":"4명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#4','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C3',1,'mc','auto','조사한 친구를 빠뜨리지 않으려면 어떻게 하면 좋은가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X15']::text[],false,'{"seq":4,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"조사한 친구를 빠뜨리지 않으려면 어떻게 하면 좋은가요?","options":[{"t":"말한 친구의 이름을 칸에 적어 둔다","correct":true},{"t":"말한 친구는 잊어도 된다","mis":"M2-2-u5-X01"},{"t":"처음 말한 친구만 적는다","mis":"M2-2-u5-X15"}],"explanation":["말한 친구의 이름을 적어 두면 누가 말했는지 알아요.","그래서 빠뜨리거나 두 번 세지 않아요.","다 끝나면 이름 수를 반 학생 수와 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#5','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「포도」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ → 5","그래서 빈칸은 5예요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"5","correct":true},{"t":"4","mis":"M2-2-u5-X06"},{"t":"6","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감","복숭아"],"counts":[3,null,2,4,4],"unit":"명","vh":"학생 수","tally":[3,5,2,4,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#6','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C5',1,'mc','auto','표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?',ARRAY['M2-2-u5-X12']::text[],true,'{"seq":6,"concept":"M2-2-u5-C5","difficulty":1,"kind":"mc","stem":"표를 보고 그래프로 나타내려고 해요. 세로는 적어도 몇 칸으로 나누어야 하나요?","explanation":["가장 큰 수는 팥 7명이에요.","◯를 7개까지 쌓아야 하니 세로는 7칸이면 돼요.","칸이 모자라면 다 그릴 수 없고, 너무 많으면 빈 칸이 남아요."],"variant_rule":{"tg":{"ask":"rows"}},"options":[{"t":"7칸","correct":true},{"t":"21칸","mis":"M2-2-u5-X12"},{"t":"5칸","mis":"M2-2-u5-X12"}],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#7','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C6',1,'sa','auto','초코 붕어빵을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C6","difficulty":1,"kind":"sa","stem":"초코 붕어빵을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["그래프에서 「초코」 칸에 ／이 몇 개 쌓였는지 세어요.","초코 붕어빵을 좋아하는 학생은 4명이에요.","한 칸에 하나씩 — 쌓인 수가 곧 그 항목의 수예요."],"variant_rule":{"tg":{"ask":"count","src":"graph"}},"answer":["4","4명"],"asset":{"type":"pgraph","mark":"／","dir":"h","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#8','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C7',1,'mc','auto','제기차기를 가장 많이 한 모둠은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],true,'{"seq":8,"concept":"M2-2-u5-C7","difficulty":1,"kind":"mc","stem":"제기차기를 가장 많이 한 모둠은 무엇인가요?","explanation":["그래프에서 ◯가 가장 높이(길게) 쌓인 칸을 찾아요.","1모둠 5회, 2모둠 3회, 3모둠 7회, 4모둠 13회, 5모둠 8회예요 — 가장 많은 것은 4모둠(13회)이에요.","「가장 많은」을 묻는지 다시 읽어요. 앞 칸이라고 많은 게 아니에요."],"variant_rule":{"tg":{"ask":"most","src":"graph"}},"options":[{"t":"4모둠","correct":true},{"t":"2모둠","mis":"M2-2-u5-X09"},{"t":"1모둠","mis":"M2-2-u5-X07"},{"t":"3모둠","mis":"M2-2-u5-X07"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#9','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C2',2,'mc','auto','공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"공기놀이를 원하는 학생과 딱지치기를 원하는 학생은 모두 몇 명인가요?","explanation":["공기놀이를 원하는 학생은 5명, 딱지치기를 원하는 학생은 5명이에요.","5 + 5 = 10이니 모두 10명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"10명","correct":true},{"t":"0명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#10','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 7 + 5 + 3 + 4 = 19예요.","19 + □ = 21이니 □ = 2예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["2"],"asset":{"type":"ftable","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,null,3,4],"unit":"명","vh":"학생 수","total":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#11','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C6',2,'mc','auto','표를 보고 그래프를 완성하려고 해요. 슈크림 칸에는 ／을 몇 개 그려야 하나요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":11,"concept":"M2-2-u5-C6","difficulty":2,"kind":"mc","stem":"표를 보고 그래프를 완성하려고 해요. 슈크림 칸에는 ／을 몇 개 그려야 하나요?","explanation":["표에서 슈크림은 5명이에요.","그래프의 수는 표의 수와 같아야 해요 — ／을 5개 그려요.","맨 아래 칸부터 빠짐없이 한 칸에 하나씩 그려요."],"variant_rule":{"tg":{"ask":"gblank"}},"options":[{"t":"5개","correct":true},{"t":"6개","mis":"M2-2-u5-X11"},{"t":"4개","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"／","dir":"v","topic":"bread","title":"재우네 반 학생들이 좋아하는 붕어빵의 종류별 학생 수","head":"종류","cols":["팥","슈크림","고구마","치즈","초코"],"counts":[7,5,2,3,4],"unit":"명","vh":"학생 수","table":true,"blank":[1]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#12','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C7',2,'sa','auto','가을에 태어난 학생은 여름에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-2-u5-C7","difficulty":2,"kind":"sa","stem":"가을에 태어난 학생은 여름에 태어난 학생보다 몇 명 더 많은가요? 숫자로 쓰세요.","explanation":["가을에 태어난 학생은 6명, 여름에 태어난 학생은 4명이에요.","6 − 4 = 2이니 2명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"answer":["2","2명"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#13','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C8',2,'mc','auto','표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?',ARRAY['M2-2-u5-X11']::text[],true,'{"seq":13,"concept":"M2-2-u5-C8","difficulty":2,"kind":"mc","stem":"표를 보고 그래프로 나타냈어요. 잘못 옮긴 곳은 어디인가요?","explanation":["표에서 여름은 4명인데 그래프에는 ◯가 5개예요.","표와 그래프의 수는 반드시 같아야 해요.","다른 칸은 표의 수와 그래프의 수가 같아요."],"variant_rule":{"tg":{"ask":"wrong"}},"options":[{"t":"여름 — 표는 4명인데 ◯를 5개 그렸다","correct":true},{"t":"봄 — 표는 7명인데 ◯를 6개 그렸다","mis":"M2-2-u5-X11"},{"t":"가을 — 표는 6명인데 ◯를 5개 그렸다","mis":"M2-2-u5-X11"},{"t":"겨울 — 표는 3명인데 ◯를 4개 그렸다","mis":"M2-2-u5-X11"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","table":true,"drawn":[7,5,6,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#14','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C3',2,'ox','auto','조사할 때 한 친구에게 두 번 물어보면 더 정확해져요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":14,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"조사할 때 한 친구에게 두 번 물어보면 더 정확해져요.","answer":"X","reason_options":[{"t":"같은 친구를 두 번 세게 되어 수가 틀리니까","correct":true},{"t":"두 번 물으면 확인이 되니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["한 친구는 한 번만 세야 해요.","두 번 물어 두 번 적으면 수가 하나 늘어나요.","／ 표시를 하며 세면 두 번 세지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#15','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C5',2,'mc','auto','그래프를 다 그린 뒤 마지막으로 할 일은 무엇인가요?',ARRAY['M2-2-u5-X11','M2-2-u5-X12']::text[],false,'{"seq":15,"concept":"M2-2-u5-C5","difficulty":2,"kind":"mc","stem":"그래프를 다 그린 뒤 마지막으로 할 일은 무엇인가요?","options":[{"t":"제목을 쓴다","correct":true},{"t":"◯를 하나 더 그린다","mis":"M2-2-u5-X11"},{"t":"칸을 더 나눈다","mis":"M2-2-u5-X12"}],"explanation":["그래프를 다 그리면 제목을 써요.","제목은 무엇을 나타낸 그래프인지 알려 줘요.","◯를 더 그리면 표와 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#16','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C1',2,'ox','auto','자료를 표로 나타내면 누가 무엇을 골랐는지 더 잘 알 수 있어요.',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":16,"concept":"M2-2-u5-C1","difficulty":2,"kind":"ox","stem":"자료를 표로 나타내면 누가 무엇을 골랐는지 더 잘 알 수 있어요.","answer":"X","reason_options":[{"t":"표에는 이름 대신 수를 적어서 누가 골랐는지는 안 보이니까","correct":true},{"t":"표는 모든 것을 더 잘 보여 주니까","mis":"M2-2-u5-X16"}],"mis":"M2-2-u5-X16","explanation":["표에는 이름 대신 수를 적어요.","누가 무엇을 골랐는지는 자료에서 알아요.","표는 활동별 수를 한눈에 알기 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#17','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C7',3,'mc','auto','4명보다 많은 동물은 모두 몇 가지인가요?',ARRAY['M2-2-u5-X14','M2-2-u5-X04']::text[],true,'{"seq":17,"concept":"M2-2-u5-C7","difficulty":3,"kind":"mc","stem":"4명보다 많은 동물은 모두 몇 가지인가요?","explanation":["4명인 칸 위에 선을 긋고 그 위에 ◯가 있는 동물을 찾아요.","개, 고양이 — 2가지예요.","「4명보다 많은」에 딱 4명인 것은 들어가지 않아요."],"variant_rule":{"tg":{"ask":"more"}},"options":[{"t":"2가지","correct":true},{"t":"3가지","mis":"M2-2-u5-X14"},{"t":"11가지","mis":"M2-2-u5-X04"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#18','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C6',3,'mc','auto','그래프를 보세요. 잘못 그린 까닭은 무엇인가요?',ARRAY['M2-2-u5-X10','M2-2-u5-X13']::text[],true,'{"seq":18,"concept":"M2-2-u5-C6","difficulty":3,"kind":"mc","stem":"그래프를 보세요. 잘못 그린 까닭은 무엇인가요?","explanation":["「공기놀이」 칸을 보세요.","◯가 위에서부터 채워져 있어요.","◯는 언제나 맨 아래부터 빠짐없이, 한 가지 기호로 그려요."],"variant_rule":{"tg":{"ask":"bad"}},"options":[{"t":"맨 아래 칸부터 채우지 않고 위에서부터 그렸다","correct":true},{"t":"중간 칸을 건너뛰고 그렸다","mis":"M2-2-u5-X10"},{"t":"기호를 섞어서 그렸다","mis":"M2-2-u5-X13"}],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"play","title":"동호네 반 학생들이 좋아하는 전통 놀이별 학생 수","head":"전통 놀이","cols":["비사치기","투호 놀이","제기차기","공기놀이"],"counts":[3,8,2,9],"unit":"명","vh":"학생 수","bad":{"col":3,"how":"top"},"rows":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#19','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C8',3,'error','auto','계절 조사 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X16']::text[],false,'{"seq":19,"concept":"M2-2-u5-C8","difficulty":3,"kind":"error","stem":"계절 조사 결과를 쪽지에 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"도윤 — 「우리 반은 모두 7명입니다.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"나린 — 「봄에 태어난 학생이 7명으로 가장 많습니다.」","mis":"M2-2-u5-X16"},{"t":"서아 — 「우리 반은 모두 20명입니다.」","mis":"M2-2-u5-X16"}],"explanation":["반 학생 수는 합계 20명이에요.","7은 봄 한 칸의 수예요.","합계와 한 칸의 수를 섞으면 안 돼요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#20','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C2',3,'mc','auto','보드게임을 원하지 않는 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":20,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"보드게임을 원하지 않는 학생은 모두 몇 명인가요?","options":[{"t":"14명","correct":true},{"t":"6명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"15명","mis":"M2-2-u5-X01"}],"explanation":["보드게임이 아닌 놀이는 땅따먹기·공기놀이·딱지치기예요.","4 + 5 + 5 = 14예요.","합계 20에서 보드게임 6명을 빼도 14예요."],"asset":{"type":"ftable","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#21','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C4',3,'error','auto','친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X15']::text[],false,'{"seq":21,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"민수 — 합계 칸에 가장 큰 수 6을 적었다","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"지아 — 동물별 학생 수를 세어 적었다","mis":"M2-2-u5-X15"},{"t":"세미 — 6 + 3 + 5 + 2 + 4 = 20을 합계에 적었다","mis":"M2-2-u5-X15"}],"explanation":["합계는 항목별 수를 모두 더한 수예요.","가장 큰 수 6을 합계에 적으면 안 돼요.","6 + 3 + 5 + 2 + 4 = 20이 합계예요."],"asset":{"type":"ftable","topic":"animal","title":"수찬이네 반 학생들이 좋아하는 동물별 학생 수","head":"동물","cols":["개","앵무새","고양이","토끼","금붕어"],"counts":[6,3,5,2,4],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#22','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C5',3,'ox','auto','가로에 놀이, 세로에 학생 수를 둔 그래프를 가로와 세로를 바꾸어 그려도 돼요.',ARRAY['M2-2-u5-X13']::text[],false,'{"seq":22,"concept":"M2-2-u5-C5","difficulty":3,"kind":"ox","stem":"가로에 놀이, 세로에 학생 수를 둔 그래프를 가로와 세로를 바꾸어 그려도 돼요.","answer":"O","reason_options":[{"t":"자리만 바뀌고 놀이별 학생 수는 같으니까","correct":true},{"t":"바꾸면 수가 달라져서 안 되니까","mis":"M2-2-u5-X13"}],"mis":"M2-2-u5-X13","explanation":["가로와 세로를 바꾸어 그려도 돼요.","놀이 종류와 학생 수는 같아요.","자리와 기호만 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#23','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C7',4,'essay','teacher','지수네 반 제기차기 그래프에서 가장 많이 한 모둠과 가장 적게 한 모둠의 횟수 차이를 구하고, 그래프에서 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u5-C7","difficulty":4,"kind":"essay","stem":"지수네 반 제기차기 그래프에서 가장 많이 한 모둠과 가장 적게 한 모둠의 횟수 차이를 구하고, 그래프에서 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: ◯가 가장 높이 쌓인 4모둠이 13회로 가장 많고, 가장 낮은 2모둠이 3회로 가장 적다. 13 − 3 = 10이므로 차이는 10회이다.","scoring_points":["4모둠 13회, 2모둠 3회를 찾았는가","높이로 찾았음을 썼는가","13 − 3 = 10회를 구했는가"]},"explanation":["◯가 가장 높은 4모둠은 13회, 가장 낮은 2모둠은 3회예요.","많고 적음은 높이로 찾아요.","13 − 3 = 10회 차이예요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"jegi","title":"지수네 반 모둠별 제기차기 횟수","head":"모둠","cols":["1모둠","2모둠","3모둠","4모둠","5모둠"],"counts":[5,3,7,13,8],"unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#24','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C8',4,'essay','teacher','표를 보고 그래프로 옮길 때 지켜야 할 것 두 가지를 쓰고, 잘못 옮기면 어떤 일이 생기는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u5-C8","difficulty":4,"kind":"essay","stem":"표를 보고 그래프로 옮길 때 지켜야 할 것 두 가지를 쓰고, 잘못 옮기면 어떤 일이 생기는지 설명해 보세요.","answer_guide":{"answer":"예: 표의 수와 그래프의 ◯ 수를 같게 그려야 하고, ◯는 맨 아래부터 빠짐없이 한 칸에 하나씩 그려야 한다. 잘못 옮기면 그래프를 보고 몇 명인지, 어느 것이 많은지 잘못 알게 된다.","scoring_points":["표와 같은 수로 옮김을 썼는가","맨 아래부터 빠짐없이 그림을 썼는가","잘못 옮기면 생기는 일을 썼는가"]},"explanation":["표의 수와 ◯ 수는 같아야 해요.","◯는 맨 아래부터 빠짐없이 그려요.","잘못 옮기면 수와 많고 적음을 잘못 읽어요."],"asset":{"type":"pgraph","mark":"◯","dir":"v","topic":"game","title":"우리 반 학생들이 원하는 교실 놀이별 학생 수","head":"교실 놀이","cols":["땅따먹기","공기놀이","보드게임","딱지치기"],"counts":[4,5,6,5],"unit":"명","vh":"학생 수","table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_review_d#25','math',2,2,'u5','','g2_2_math_u5_review_d','unit_review','M2-2-u5-C3',4,'essay','teacher','「내가 좋아하는 친구들에게만 물어보기」가 조사 방법으로 알맞지 않은 까닭을 설명하고, 알맞은 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u5-C3","difficulty":4,"kind":"essay","stem":"「내가 좋아하는 친구들에게만 물어보기」가 조사 방법으로 알맞지 않은 까닭을 설명하고, 알맞은 방법을 써 보세요.","answer_guide":{"answer":"예: 몇 명에게만 물으면 빠진 친구가 생겨 우리 반 전체의 결과가 아니다. 한 사람씩 차례로 말하게 하거나 계절별로 손을 들게 해서 모두 조사해야 한다.","scoring_points":["빠진 친구가 생김을 썼는가","전체의 결과가 아님을 썼는가","알맞은 방법을 하나 썼는가"]},"explanation":["몇 명만 조사하면 빠진 친구가 생겨요.","그러면 우리 반 전체의 결과가 아니에요.","모두에게 말하기나 손 들기로 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
